function ensureDataModel(){
  const defaults={products:[],categories:[],units:[],departments:[],customers:[],suppliers:[],vehicles:[],drivers:[],salesRepresentatives:[],routes:[],purchases:[],sales:[],payments:[],expenses:[],returns:[],movements:[],assets:[],stocktakes:[],inventoryCounts:[],inventoryAdjustments:[],users:[],activity:[],warehouses:[],warehouseZones:[]};
  Object.entries(defaults).forEach(([key,value])=>{if(!Array.isArray(data[key]))data[key]=value});
  data.meta ||= {company:'شركة السريحي',currency:'د.ت',taxEnabled:false,theme:'light',nextInvoice:1,nextPurchase:1,nextRoute:1};
  data.meta.nextInvoice ||= 1; data.meta.nextPurchase ||= 1; data.meta.nextRoute ||= 1;
  if(data.categories.length) categories=data.categories.map(row=>typeof row==='string'?row:row.name).filter(Boolean);
  else data.categories=categories.map(name=>({id:`CAT-${name}`,name,status:'نشط'}));
  if(data.units.length) units=data.units.map(row=>typeof row==='string'?row:row.name).filter(Boolean);
  else data.units=units.map(name=>({id:`UNIT-${name}`,name,status:'نشط'}));
  if(!data.departments.length) data.departments=['المخزن الرئيسي','المبيعات','التوزيع','الإدارة'].map(name=>({id:`DEPT-${name}`,name,status:'نشط'}));
  if(!data.drivers.length) data.drivers=[...new Set(data.vehicles.map(row=>row.driver).filter(Boolean))].map(name=>({id:uid('DRV'),name,status:'نشط'}));
  if(!data.salesRepresentatives.length) data.salesRepresentatives=[...new Set(data.vehicles.map(row=>row.seller).filter(Boolean))].map(name=>({id:uid('REP'),name,status:'نشط'}));
  data.products.forEach(p=>{p.stock=Number(p.stock)||0;p.damaged=Number(p.damaged)||0;p.status ||= 'نشط';p.min=Number(p.min)||0;p.buy=Number(p.buy)||0;p.sell=Number(p.sell)||0});
  data.routes.forEach(r=>{r.loaded ||= [];r.sold ||= [];r.returned ||= [];r.losses ||= [];r.status ||= 'مفتوحة'});
  data.assets.forEach(a=>{a.total=Number(a.total)||0;a.available=Number(a.available)||0;a.withCustomers=Number(a.withCustomers)||0;a.withVehicles=Number(a.withVehicles)||0;a.damaged=Number(a.damaged)||0;a.lost=Number(a.lost)||0;a.movements ||= []});
}
