function save(){
  if(!dbReady) return;
  clearTimeout(saveTimer);
  saveTimer=setTimeout(()=>db.saveSnapshot(data).catch(error=>{console.error(error);showToast('تعذر حفظ البيانات في قاعدة البيانات، لم يتم تغيير السجل المخزن.','error')}),40);
}
function product(id){return data.products.find(x=>x.id===id)}
function customer(id){return data.customers.find(x=>x.id===id)}
function supplier(id){return data.suppliers.find(x=>x.id===id)}
function vehicle(id){return data.vehicles.find(x=>x.id===id)}
function route(id){return data.routes.find(x=>x.id===id)}
function addActivity(action,detail,ref='—'){data.activity.unshift({id:uid('AC'),date:`${today()} ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false})}`,user:'محمد السريحي',action,detail,ref});data.activity=data.activity.slice(0,100)}
function movement(productId,qty,type,from,to,ref,note=''){data.movements.unshift({id:uid('MV'),date:today(),productId,qty,type,from,to,ref,note});}
function productName(id){return product(id)?.name || 'صنف محذوف'}
function routeLoaded(r,pid){return (r.loaded||[]).find(x=>x.productId===pid)?.qty||0}
function routeSold(r,pid){return (r.sold||[]).filter(x=>x.productId===pid).reduce((s,x)=>s+x.qty,0)}
function routeReturned(r,pid){return (r.returned||[]).find(x=>x.productId===pid)?.qty||0}
function routeLost(r,pid){return (r.losses||[]).find(x=>x.productId===pid)?.qty||0}
function routeAvailable(r,pid){return routeLoaded(r,pid)-routeSold(r,pid)-routeReturned(r,pid)-routeLost(r,pid)}
function vehicleCurrent(vId){return data.routes.filter(r=>r.vehicleId===vId&&r.status==='مفتوحة').reduce((all,r)=>{(r.loaded||[]).forEach(x=>all[x.productId]=(all[x.productId]||0)+routeAvailable(r,x.productId));return all},{});}
function stockValue(){return data.products.reduce((s,p)=>s+p.stock*p.buy,0)}
function totalSales(period){return data.sales.filter(s=>!period||s.date>=period).reduce((a,s)=>a+s.total,0)}
function sum(list,key='amount'){return list.reduce((total,item)=>total+(Number(item[key])||0),0)}
function dateInRange(value,from='',to=''){const date=String(value||'').slice(0,10);return (!from||date>=from)&&(!to||date<=to)}
function salesForPeriod(){return data.sales.filter(s=>dateInRange(s.date,filters.reportFrom,filters.reportTo))}
function purchasesForPeriod(){return data.purchases.filter(p=>dateInRange(p.date,filters.reportFrom,filters.reportTo))}
function inventoryByCategory(){return categories.map(category=>({category,qty:sum(data.products.filter(p=>p.category===category),'stock')})).filter(x=>x.qty>0)}
function activeProducts(){return data.products.filter(p=>p.status!=='غير نشط')}
function validatePositive(value,label,allowZero=false){const number=Number(value);if(!Number.isFinite(number)||(!allowZero&&number<=0)||(allowZero&&number<0)){showToast(`${label} يجب أن يكون رقمًا ${allowZero?'غير سالب':'موجبًا'}`,'error');return null}return number}
function updatePartyBalance(party,delta,kind){if(!party)return;if(kind==='customer'){party.sales=Number(party.sales)||0;party.payments=Number(party.payments)||0;party.returns=Number(party.returns)||0;party.balance=Number(party.balance)||0;if(delta.sale)party.sales+=delta.sale;if(delta.payment)party.payments+=delta.payment;if(delta.return)party.returns+=delta.return;party.balance+=Number(delta.sale||0)-Number(delta.payment||0)-Number(delta.return||0)}else{party.purchases=Number(party.purchases)||0;party.payments=Number(party.payments)||0;party.returns=Number(party.returns)||0;party.balance=Number(party.balance)||0;if(delta.purchase)party.purchases+=delta.purchase;if(delta.payment)party.payments+=delta.payment;if(delta.return)party.returns+=delta.return;party.balance+=Number(delta.purchase||0)-Number(delta.payment||0)-Number(delta.return||0)}party.balance=Math.max(0,party.balance)}
function exportCollection(name,rows){download(`السريحي-${name}-${today()}.json`,JSON.stringify(rows,null,2));showToast(`تم تصدير ${name} بنجاح`)}
function decorateNumericContent(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[]; let node;
  while(node=walker.nextNode()){
    const parent=node.parentElement;
    if(!parent || parent.closest('.number,.date,.date-time,[data-no-number]') || ['SCRIPT','STYLE','INPUT','TEXTAREA','SELECT','OPTION'].includes(parent.tagName)) continue;
    if(/\d/.test(node.nodeValue)) nodes.push(node);
  }
  const numeric=/[-+]?\d[\d,]*(?:\.\d+)?%?/g;
  nodes.forEach(textNode=>{
    const text=textNode.nodeValue, frag=document.createDocumentFragment(); let last=0, match;
    numeric.lastIndex=0;
    while(match=numeric.exec(text)){
      if(match.index>last) frag.append(text.slice(last,match.index));
      const span=document.createElement('span'); span.className='number'; span.dir='ltr'; span.textContent=match[0]; frag.append(span); last=match.index+match[0].length;
    }
    if(last<text.length) frag.append(text.slice(last));
    if(last) textNode.replaceWith(frag);
  });
}
function render(){
  document.querySelectorAll('.page-section').forEach(x=>x.classList.remove('active'));
  const section=document.querySelector(`#section-${activeSection}`);
  if(!section) return;
  section.classList.add('active');
  document.querySelectorAll('.nav-item[data-section]').forEach(x=>x.classList.toggle('active',x.dataset.section===activeSection));
  document.getElementById('breadcrumb').innerHTML=`${navNames[activeSection]} <span>/</span> ${activeSection==='dashboard'?'نظرة عامة':'إدارة '+navNames[activeSection]}`;
  const renderers={dashboard:renderDashboard,products:renderProducts,warehouses:renderWarehouses,routes:renderRoutes,drivers:renderDrivers,sales:renderSalesV2,returns:renderReturns,purchases:renderPurchasesV2,customers:renderCustomers,suppliers:renderSuppliers,assets:renderAssetsV2,payments:renderPaymentsV2,expenses:renderExpenses,reports:renderReportsV2,stocktake:renderStocktake,invoices:renderInvoices,users:renderUsers,settings:renderSettings};
  section.innerHTML=renderers[activeSection]();
  if(activeSection==='products'){
    const categorySelect=section.querySelector('.product-category-filter');
    if(categorySelect){categorySelect.dataset.filter='productsCategory';categorySelect.value=filters.productsCategory||'';const stockSelect=document.createElement('select');stockSelect.className='select-control filter-select';stockSelect.dataset.filter='productsStock';stockSelect.innerHTML='<option value="">كل حالات المخزون</option><option value="low">منخفض المخزون</option><option value="ok">متوفر</option>';stockSelect.value=filters.productsStock||'';const zoneSelect=document.createElement('select');zoneSelect.className='select-control filter-select';zoneSelect.dataset.filter='productsZone';zoneSelect.innerHTML='<option value="">كل المناطق</option>'+['A','B','C','D','E','F','G'].map(zone=>'<option value="'+zone+'">منطقة '+zone+'</option>').join('');zoneSelect.value=filters.productsZone||'';categorySelect.after(stockSelect,zoneSelect)}
  }
  if(activeSection==='stocktake')section.querySelectorAll('.summary-item').forEach(item=>{if(item.textContent.includes('تسويات هذا الشهر')){const strong=item.querySelector('strong');if(strong)strong.textContent=data.movements.filter(m=>m.type==='تسوية جرد'&&String(m.date).slice(0,7)===today().slice(0,7)).length}});
  decorateNumericContent(section);
}
function pageTitle(title,sub,actions=''){return `<div class="page-title-row"><div class="page-title"><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function metric(label,value,icon,foot,trend=''){return `<div class="card metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-bottom">${trend?`<span class="${trend.startsWith('+')?'trend-up':'trend-down'}">${trend}</span> `:''}${foot}</div></div>`}
function tableSearch(placeholder='بحث...'){return `<div class="search-box"><span>⌕</span><input class="local-search" placeholder="${placeholder}" value="${esc(searchTerm)}" /></div>`}
function paged(key,list){const size=20,pages=Math.max(1,Math.ceil(list.length/size));pageState[key]=Math.min(Math.max(1,pageState[key]||1),pages);return {rows:list.slice((pageState[key]-1)*size,pageState[key]*size),pages,size,total:list.length}}
function pagination(key,total){const size=20,pages=Math.max(1,Math.ceil(total/size)),page=Math.min(pageState[key]||1,pages);if(total<=size)return '';return `<div class="pagination"><span class="muted small">${num(total)} سجل · صفحة ${page} من ${pages}</span><div class="actions"><button class="btn btn-light btn-sm" data-page="${key}" data-page-number="${Math.max(1,page-1)}" ${page<=1?'disabled':''}>السابق</button><button class="btn btn-light btn-sm" data-page="${key}" data-page-number="${Math.min(pages,page+1)}" ${page>=pages?'disabled':''}>التالي</button></div></div>`}
function statusBadge(s){const map={'نشط':'success','مفتوحة':'warning','مغلقة':'success','متاحة':'success','صيانة':'danger','مدفوعة':'success','آجل':'warning','مسودة':'neutral','معلق':'warning'};return `<span class="badge badge-${map[s]||'blue'}">${s}</span>`}
function renderDashboard(){
  const low=activeProducts().filter(p=>p.stock<=p.min).length, out=activeProducts().filter(p=>p.stock===0).length, open=data.routes.filter(r=>r.status==='مفتوحة').length, todaySales=data.sales.filter(s=>s.date===today()).reduce((a,s)=>a+s.total,0), monthSales=data.sales.filter(s=>s.date.slice(0,7)===today().slice(0,7)).reduce((a,s)=>a+s.total,0);
  const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const iso=d.toISOString().slice(0,10);return {iso,label:d.getDate()+'/'+(d.getMonth()+1),value:sum(data.sales.filter(s=>s.date===iso),'total')}});
  const maxBar=Math.max(1,...days.map(x=>x.value));
  const stockGroups=inventoryByCategory(), stockTotal=Math.max(1,sum(stockGroups,'qty'));
  return `${pageTitle('لوحة التحكم','نظرة شاملة على عمليات شركة السريحي لهذا اليوم',`<button class="btn btn-light" data-action="refresh">↻ تحديث</button><button class="btn btn-primary" data-action="open-sale">＋ فاتورة بيع</button>`)}
    <div class="metrics-grid">
      ${metric('قيمة المخزون',money(stockValue()),'▣','بسعر الشراء','')}${metric('عدد الأصناف',num(data.products.length),'▦','أصناف مسجلة','')}${metric('منخفض المخزون',num(low),'!','يحتاج مراجعة','')}${metric('نفد من المخزون',num(out),'×','أصناف نفدت','')}${metric('مبيعات اليوم',money(todaySales),'↗','حتى الآن','')}${metric('مبيعات الشهر',money(monthSales),'↗','الشهر الحالي','')}${metric('إجمالي المشتريات',money(data.purchases.reduce((a,p)=>a+p.total,0)),'⇩',`${data.purchases.length} فواتير شراء`,'')}${metric('العملاء',num(data.customers.length),'♙','عملاء مسجلون','')}${metric('الموردون',num(data.suppliers.length),'♧','موردون مسجلون','')}${metric('الجولات المفتوحة',num(open),'▱','جولات نشطة','')}${metric('الفواتير اليوم',num(data.sales.filter(s=>s.date===today()).length),'▤','فواتير مبيعات','')}
    </div>
    <div class="dashboard-grid"><div class="card chart-card"><div class="card-header"><h3>المبيعات اليومية <span class="sub">آخر 7 أيام</span></h3></div><div class="chart-area" dir="ltr"><div class="chart-y"><span>${money(maxBar)}</span><span>${money(maxBar*.75)}</span><span>${money(maxBar*.5)}</span><span>${money(maxBar*.25)}</span><span>0</span></div><div class="bars">${days.map(b=>`<div class="bar-col" title="${b.iso}: ${money(b.value)}"><div class="bar" style="height:${Math.max(2,b.value/maxBar*100)}%"></div><label>${b.label}</label></div>`).join('')}</div></div></div>
      <div class="card chart-card"><div class="card-header"><h3>توزيع المخزون حسب التصنيف</h3><button class="btn btn-light btn-sm" data-section="reports">التقرير</button></div><div class="donut-wrap"><div class="donut" style="background:${stockGroups.length?`conic-gradient(${stockGroups.map((x,i)=>`${['#1d5fe7','#74a0fa','#8a65dd','#e4a43e','#2bbf8a'][i%5]} 0 ${(stockGroups.slice(0,i+1).reduce((a,y)=>a+y.qty,0)/stockTotal*100).toFixed(2)}%`).join(',')})`:'var(--line)'}"></div><div class="legend">${stockGroups.slice(0,5).map((x,i)=>`<div class="legend-item"><i class="legend-dot" style="background:${['#1d5fe7','#74a0fa','#8a65dd','#e4a43e','#2bbf8a'][i%5]}"></i> ${x.category} <b>${Math.round(x.qty/stockTotal*100)}%</b></div>`).join('')||'<span class="muted">لا توجد بيانات مخزون</span>'}</div></div></div></div>
    <div class="dashboard-bottom"><div class="card"><div class="card-header"><h3>التنبيهات المهمة</h3><span class="badge badge-danger">${low+open} تنبيهات</span></div><div class="card-body alert-list">${low?`<div class="alert-row"><div class="alert-icon red">!</div><div class="alert-copy"><strong>${low} أصناف وصلت للحد الأدنى</strong><span>راجع مستويات المخزون وأعد الطلب</span></div><button class="btn btn-light btn-sm" data-section="products">فتح</button></div>`:''}<div class="alert-row"><div class="alert-icon amber">◷</div><div class="alert-copy"><strong>${open} جولة بيع لم تغلق</strong><span>بضاعة موجودة مع السيارات</span></div><button class="btn btn-light btn-sm" data-section="routes">عرض</button></div><div class="alert-row"><div class="alert-icon blue">◉</div><div class="alert-copy"><strong>${data.customers.filter(c=>c.balance>0).length} عملاء لديهم مبالغ مستحقة</strong><span>إجمالي ${money(data.customers.reduce((a,c)=>a+c.balance,0))}</span></div><button class="btn btn-light btn-sm" data-section="customers">عرض</button></div></div></div>
      <div class="card"><div class="card-header"><h3>المخزون المنخفض</h3><button class="btn btn-light btn-sm" data-section="products">كل الأصناف</button></div><div class="card-body stock-list">${data.products.filter(p=>p.stock<=p.min+15).slice(0,4).map(p=>`<div class="stock-row"><div class="product-avatar">${initials(p.name)}</div><div class="stock-info"><strong>${p.name}</strong><span>${num(p.stock)} ${p.unit} من ${num(p.min)} حد أدنى</span><div class="progress"><i class="${p.stock<=p.min?'danger':'warn'}" style="width:${Math.min(100,p.stock/p.max*100)}%"></i></div></div><b class="small">${num(p.stock)}</b></div>`).join('')}</div></div>
      <div class="card"><div class="card-header"><h3>آخر النشاطات</h3><button class="btn btn-light btn-sm" data-section="users">السجل الكامل</button></div><div class="card-body activity-list">${data.activity.slice(0,4).map(a=>`<div class="activity-row"><div class="activity-avatar">${initials(a.user)}</div><div><strong>${a.action}</strong><span>${a.detail} · ${fmtDateTime(a.date)}</span></div></div>`).join('')}</div></div></div>`;
}
function renderProducts(){
  const list=data.products.filter(p=>(!searchTerm||[p.name,p.sku,p.barcode,p.category,p.zone,p.rack].join(' ').toLowerCase().includes(searchTerm.toLowerCase()))&&(!filters.productsCategory||p.category===filters.productsCategory)&&(!filters.productsZone||p.zone===filters.productsZone)&&(!filters.productsStock||(filters.productsStock==='low'?p.stock<=p.min:p.stock>p.min))),page=paged('products',list),rows=page.rows;
  return `${pageTitle('الأصناف والمنتجات','إدارة بيانات المنتجات والوحدات والأسعار ومواقع التخزين',`<button class="btn btn-light" data-action="export-products">⇩ تصدير</button><button class="btn btn-primary" data-action="add-product">＋ إضافة صنف</button>`)}
    <div class="summary-strip">${['إجمالي الأصناف|'+data.products.length+' صنف|blue','أصناف نشطة|'+data.products.filter(p=>p.status==='نشط').length+' صنف|green','منخفضة المخزون|'+data.products.filter(p=>p.stock<=p.min).length+' أصناف|red','قيمة المخزون|'+money(stockValue())+'|violet'].map(x=>{let [a,b,c]=x.split('|');return `<div class="summary-item"><span>${a}</span><strong class="stat-color ${c}">${b}</strong></div>`}).join('')}</div>
    <div class="card table-card"><div class="card-header"><div class="table-tools">${tableSearch('ابحث بالاسم أو الكود أو الباركود')}<select class="select-control filter-select product-category-filter"><option value="">كل التصنيفات</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select></div><span class="muted small">${list.length} نتيجة</span></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>التصنيف</th><th>الوحدة</th><th>الرصيد</th><th>الأسعار</th><th>الموقع</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="table-product"><div class="product-avatar">${initials(p.name)}</div><div><strong>${p.name}</strong><span>${p.sku} · ${p.barcode}</span></div></div></td><td>${p.category}</td><td>${p.unit}<span class="muted small"> · ${p.pack} قطعة</span></td><td><b>${num(p.stock)}</b> <span class="muted small">${p.unit}</span>${p.stock<=p.min?'<br><span class="badge badge-danger">منخفض</span>':''}</td><td><span class="small">بيع: </span><b>${money(p.sell)}</b><br><span class="small muted">شراء: ${money(p.buy)}</span></td><td>${p.zone} / ${p.rack}</td><td>${statusBadge(p.status)}</td><td><div class="row-actions"><button class="btn btn-light btn-sm btn-icon" data-action="edit-product" data-id="${p.id}" title="تعديل">✎</button><button class="btn btn-light btn-sm btn-icon" data-action="product-movements" data-id="${p.id}" title="الحركات">↕</button><button class="btn btn-danger btn-sm btn-icon" data-action="delete-product" data-id="${p.id}" title="حذف">🗑️</button></div></td></tr>`).join('')||`<tr><td colspan="8" class="empty">لا توجد أصناف مطابقة</td></tr>`}</tbody></table></div>${pagination('products',list.length)}</div>`;
}
function renderWarehouses(){
  const zones=(data.warehouseZones?.map(z=>z.code).filter(Boolean).length?data.warehouseZones.map(z=>z.code):['A','B','C','D','E','F','G']);
  const capacity=Math.max(1,data.products.reduce((n,p)=>n+(Number(p.max)||0),0)),used=Math.min(100,Math.round(data.products.reduce((n,p)=>n+(Number(p.stock)||0),0)/capacity*100));
  return `${pageTitle('المستودعات','مراقبة أرصدة المستودع ومواقع التخزين وحركة الأصناف',`<button class="btn btn-light" data-action="add-zone">＋ إضافة منطقة</button><button class="btn btn-primary" data-action="receive-goods">⇩ استلام بضاعة</button>`)}
    <div class="warehouse-layout"><div class="card"><div class="card-header"><h3>خريطة المستودع الرئيسي</h3><span class="badge badge-success">مفتوح</span></div><div class="card-body"><div class="zone-grid">${zones.map(z=>{let items=data.products.filter(p=>p.zone===z), qty=items.reduce((a,p)=>a+p.stock,0);return `<div class="zone"><strong>${z}</strong><span>${items.length} أصناف</span><span class="zone-count">${num(qty)} وحدة</span><small class="muted">${items.map(p=>p.name).slice(0,2).join('، ')||'فارغة'}</small></div>`}).join('')}</div><div class="card" style="margin-top:14px;border-style:dashed"><div class="card-body"><div style="display:flex;justify-content:space-between;align-items:center"><div><b>مؤشر الطاقة التخزينية</b><div class="muted small">المستودع الرئيسي · ${used}% مستخدم</div></div><strong class="stat-color">${used}%</strong></div><div class="progress" style="height:8px;margin-top:10px"><i style="width:${used}%"></i></div></div></div></div></div><div class="card table-card"><div class="card-header"><h3>حالة المخزون</h3><div class="table-tools">${tableSearch('بحث في المخزون')}<select class="select-control filter-select" data-filter="warehouseStock"><option value="">كل الحالات</option><option value="available">متوفر</option><option value="low">منخفض</option></select></div></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>الرصيد المتاح</th><th>الحد الأدنى</th><th>الموقع</th><th>قيمة المخزون</th><th>الحالة</th><th></th></tr></thead><tbody>${data.products.filter(p=>(!searchTerm||p.name.includes(searchTerm)||p.sku.includes(searchTerm))&&(!filters.warehouseStock||(filters.warehouseStock==='low'?p.stock<=p.min:p.stock>p.min))).map(p=>`<tr><td><div class="table-product"><div class="product-avatar">${initials(p.name)}</div><div><strong>${p.name}</strong><span>${p.sku}</span></div></div></td><td><b>${num(p.stock)}</b> ${p.unit}</td><td>${num(p.min)}</td><td>${p.zone} / ${p.rack}</td><td>${money(p.stock*p.buy)}</td><td>${p.stock<=p.min?'<span class="badge badge-danger">منخفض</span>':'<span class="badge badge-success">جيد</span>'}</td><td><button class="btn btn-light btn-sm" data-action="product-movements" data-id="${p.id}">الحركة</button></td></tr>`).join('')}</tbody></table></div></div></div>`;
}
function renderRoutes(){
  const open=data.routes.filter(r=>r.status==='مفتوحة').length, current=data.routes.filter(r=>r.status==='مفتوحة').reduce((a,r)=>a+(r.loaded||[]).reduce((x,i)=>x+routeAvailable(r,i.productId),0),0), routeRows=data.routes.filter(r=>!routeStatusFilter||r.status===routeStatusFilter);
  return `${pageTitle('السيارات وجولات البيع','تتبع البضاعة الخارجة مع البائعين من التحميل حتى الإغلاق',`<button class="btn btn-light" data-action="add-vehicle">＋ سيارة</button><button class="btn btn-primary" data-action="add-route">＋ جولة بيع جديدة</button>`)}
    <div class="summary-strip"><div class="summary-item"><span>الجولات المفتوحة</span><strong class="stat-color">${open}</strong></div><div class="summary-item"><span>بضاعة مع السيارات</span><strong>${num(current)} وحدة</strong></div><div class="summary-item"><span>السيارات المتاحة</span><strong>${data.vehicles.filter(v=>v.status==='متاحة').length}</strong></div><div class="summary-item"><span>الجولات المغلقة هذا الشهر</span><strong>${data.routes.filter(r=>r.status==='مغلقة').length}</strong></div></div>
    <div class="tab-bar"><button class="tab-btn ${!routeStatusFilter?'active':''}" data-action="route-filter" data-filter="">كل الجولات (${data.routes.length})</button><button class="tab-btn ${routeStatusFilter==='مفتوحة'?'active':''}" data-action="route-filter" data-filter="مفتوحة">مفتوحة (${open})</button><button class="tab-btn ${routeStatusFilter==='مغلقة'?'active':''}" data-action="route-filter" data-filter="مغلقة">مغلقة (${data.routes.filter(r=>r.status==='مغلقة').length})</button></div>
    <div class="route-cards">${routeRows.map(r=>{let v=vehicle(r.vehicleId), value=(r.loaded||[]).reduce((a,x)=>a+routeAvailable(r,x.productId)*(product(x.productId)?.sell||0),0);return `<div class="card route-card"><div class="route-card-top"><div><div class="route-code">${r.code}</div><div class="muted small">${fmtDate(r.date)} · ${r.area}</div></div>${statusBadge(r.status)}</div><div class="route-status"><span class="avatar" style="width:28px;height:28px;font-size:10px">${initials(v?.code)}</span><div><b class="small">${v?.code||'—'}</b><div class="muted small">${r.driver} · ${r.seller}</div></div></div><div style="margin:13px 0;border-top:1px solid var(--line);padding-top:12px"><div class="muted small">${r.status==='مفتوحة'?'المتبقي مع السيارة':'ملخص الجولة'}</div>${(r.loaded||[]).map(x=>`<div style="display:flex;justify-content:space-between;margin-top:5px;font-size:10px"><span>${productName(x.productId)}</span><b>${num(routeAvailable(r,x.productId))} ${product(x.productId)?.unit||''}</b></div>`).join('')}</div><div class="route-meta"><div><span>الخروج</span><strong>${r.outTime||'—'}</strong></div><div><span>قيمة البضاعة</span><strong>${money(value)}</strong></div><div><span>المبيعات</span><strong>${money(data.sales.filter(s=>s.routeId===r.id).reduce((a,s)=>a+s.total,0))}</strong></div></div><div class="actions" style="margin-top:14px">${r.status==='مفتوحة'?`<button class="btn btn-primary btn-sm" data-action="route-sale" data-id="${r.id}">＋ تسجيل بيع</button><button class="btn btn-light btn-sm" data-action="route-load" data-id="${r.id}">تحميل</button><button class="btn btn-success btn-sm" data-action="close-route" data-id="${r.id}">إغلاق الجولة</button>`:`<button class="btn btn-light btn-sm" data-action="route-detail" data-id="${r.id}">عرض التفاصيل</button>`}<button class="btn btn-light btn-sm btn-icon" title="تعديل السيارة" data-action="edit-vehicle" data-id="${r.vehicleId}">✎</button><button class="btn btn-danger btn-sm btn-icon" title="حذف السيارة" data-action="delete-vehicle" data-id="${r.vehicleId}">🗑️</button></div></div>`}).join('')||'<div class="card empty">لا توجد جولات بهذه الحالة.</div>'}</div>`;
}
function renderDrivers(){
  const driverRows=data.drivers.filter(row=>!searchTerm||[row.name,row.phone,row.code].join(' ').toLowerCase().includes(searchTerm.toLowerCase())).map(row=>`<tr><td><b>${esc(row.name)}</b></td><td>${esc(row.phone||'—')}</td><td>${esc(row.code||'—')}</td><td>${statusBadge(row.status||'نشط')}</td><td><div class="row-actions"><button class="btn btn-light btn-sm btn-icon" data-action="edit-driver" data-id="${row.id}">✎</button><button class="btn btn-danger btn-sm btn-icon" data-action="delete-driver" data-id="${row.id}">🗑️</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا يوجد سائقون</td></tr>';
  const repRows=data.salesRepresentatives.filter(row=>!searchTerm||[row.name,row.phone,row.code].join(' ').toLowerCase().includes(searchTerm.toLowerCase())).map(row=>`<tr><td><b>${esc(row.name)}</b></td><td>${esc(row.phone||'—')}</td><td>${esc(row.code||'—')}</td><td>${statusBadge(row.status||'نشط')}</td><td><div class="row-actions"><button class="btn btn-light btn-sm btn-icon" data-action="edit-representative" data-id="${row.id}">✎</button><button class="btn btn-danger btn-sm btn-icon" data-action="delete-representative" data-id="${row.id}">🗑️</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا يوجد مندوبو مبيعات</td></tr>';
  return pageTitle('السائقون والمندوبون','إدارة الأشخاص المرتبطين بالسيارات والرحلات',`${tableSearch('بحث بالاسم أو الهاتف')}<button class="btn btn-light" data-action="add-driver">＋ سائق</button><button class="btn btn-primary" data-action="add-representative">＋ مندوب</button>`)+`<div class="two-col"><div class="card table-card"><div class="card-header"><h3>السائقون <span class="sub">${data.drivers.length}</span></h3></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>الكود</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${driverRows}</tbody></table></div></div><div class="card table-card"><div class="card-header"><h3>مندوبو المبيعات <span class="sub">${data.salesRepresentatives.length}</span></h3></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>الكود</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${repRows}</tbody></table></div></div></div>`;
}
function renderSales(){
  const total=data.sales.reduce((a,s)=>a+s.total,0), due=data.sales.reduce((a,s)=>a+(s.total-s.paid),0);
  return `${pageTitle('المبيعات','فواتير المبيعات المباشرة ومبيعات جولات التوزيع',`<button class="btn btn-light" data-action="scan-barcode">▦ مسح باركود</button><button class="btn btn-primary" data-action="open-sale">＋ فاتورة بيع</button>`)}<div class="summary-strip"><div class="summary-item"><span>إجمالي المبيعات</span><strong>${money(total)}</strong></div><div class="summary-item"><span>فواتير اليوم</span><strong>${data.sales.filter(s=>s.date===today()).length}</strong></div><div class="summary-item"><span>المبيعات الآجلة</span><strong>${money(due)}</strong></div><div class="summary-item"><span>متوسط الفاتورة</span><strong>${money(data.sales.length?total/data.sales.length:0)}</strong></div></div><div class="card table-card"><div class="card-header"><div class="table-tools">${tableSearch('رقم الفاتورة أو العميل')}<select class="select-control filter-select"><option>كل طرق الدفع</option><option>نقد</option><option>تحويل</option><option>آجل</option></select></div><span class="muted small">${data.sales.length} فواتير</span></div><div class="table-wrap"><table><thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>العميل</th><th>المصدر</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th><th></th></tr></thead><tbody>${data.sales.filter(s=>!searchTerm||[s.number,customer(s.customerId)?.name].join(' ').includes(searchTerm)).map(s=>`<tr><td><b>${s.number}</b></td><td>${fmtDate(s.date)}</td><td>${customer(s.customerId)?.name||'—'}</td><td>${s.routeId?`جولة ${route(s.routeId)?.code||''}`:'المستودع'}</td><td><b>${money(s.total)}</b></td><td>${money(s.paid)}</td><td class="${s.total-s.paid?'stat-color':''}">${money(s.total-s.paid)}</td><td>${s.total-s.paid?'<span class="badge badge-warning">جزئية</span>':'<span class="badge badge-success">مدفوعة</span>'}</td><td><button class="btn btn-light btn-sm" data-action="view-invoice" data-id="${s.id}">عرض</button></td></tr>`).join('')||`<tr><td colspan="9" class="empty">لا توجد فواتير</td></tr>`}</tbody></table></div></div>`;
}
function renderReturns(){const list=(data.returns||[]).filter(r=>(!searchTerm||[r.ref,r.party,r.product,r.type].join(' ').toLowerCase().includes(searchTerm.toLowerCase()))&&(!filters.returnType||r.type===filters.returnType));const rows=list.map(r=>`<tr><td>${r.ref}</td><td>${fmtDate(r.date)}</td><td><span class="badge ${String(r.condition||'').includes('تالف')?'badge-danger':'badge-blue'}">${r.type}</span></td><td>${r.party}</td><td>${r.product} · ${r.qty} ${r.unit}</td><td>${money(r.amount)}</td><td><span class="badge badge-success">تمت المعالجة</span></td></tr>`).join('');return `${pageTitle('المرتجعات','إدارة مرتجعات العملاء والموردين والتالف',`<button class="btn btn-primary" data-action="add-return">＋ تسجيل مرتجع</button>`)}<div class="summary-strip"><div class="summary-item"><span>مرتجع المبيعات</span><strong>${money(data.customers.reduce((a,c)=>a+c.returns,0))}</strong></div><div class="summary-item"><span>مرتجع المشتريات</span><strong>${money(data.suppliers.reduce((a,s)=>a+s.returns,0))}</strong></div><div class="summary-item"><span>المخزون التالف</span><strong>${num(data.products.reduce((a,p)=>a+p.damaged,0))} وحدة</strong></div><div class="summary-item"><span>حالات هذا الشهر</span><strong>${(data.returns||[]).length}</strong></div></div><div class="card table-card"><div class="card-header"><h3>سجل المرتجعات</h3><div class="table-tools">${tableSearch('بحث برقم المستند أو الصنف')}<select class="select-control filter-select" data-filter="returnType"><option value="">كل الأنواع</option><option value="مرتجع مبيعات">مرتجع مبيعات</option><option value="مرتجع مشتريات">مرتجع مشتريات</option><option value="تالف">تالف</option></select></div></div><div class="table-wrap"><table><thead><tr><th>المرجع</th><th>التاريخ</th><th>النوع</th><th>الطرف</th><th>الأصناف</th><th>القيمة</th><th>الحالة</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="empty">لا توجد مرتجعات مسجلة بعد</td></tr>'}</tbody></table></div></div>`}
function renderPurchases(){const pending=data.purchases.filter(p=>['مسودة','معلق'].includes(p.status)).length;return `${pageTitle('المشتريات','طلبات الشراء والاستلام وفواتير الموردين',`<button class="btn btn-light" data-action="receive-goods">⇩ استلام بضاعة</button><button class="btn btn-primary" data-action="add-purchase">＋ فاتورة شراء</button>`)}<div class="summary-strip"><div class="summary-item"><span>مشتريات الشهر</span><strong>${money(data.purchases.reduce((a,p)=>a+p.total,0))}</strong></div><div class="summary-item"><span>الفواتير</span><strong>${data.purchases.length}</strong></div><div class="summary-item"><span>المستحق للموردين</span><strong>${money(data.suppliers.reduce((a,s)=>a+s.balance,0))}</strong></div><div class="summary-item"><span>طلبات قيد الانتظار</span><strong>${pending}</strong></div></div><div class="card table-card"><div class="card-header"><div class="table-tools">${tableSearch('رقم المستند أو المورد')}<select class="select-control filter-select" data-filter="purchaseStatus"><option value="">كل الحالات</option><option value="مدفوعة">مدفوعة</option><option value="آجل">آجل</option></select></div></div><div class="table-wrap"><table><thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>المورد</th><th>الأصناف</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th><th></th></tr></thead><tbody>${data.purchases.filter(p=>(!searchTerm||[p.number,supplier(p.supplierId)?.name].join(' ').includes(searchTerm))&&(!filters.purchaseStatus||p.status===filters.purchaseStatus)).map(p=>`<tr><td><b>${p.number}</b><br><span class="muted small">${p.doc||''}</span></td><td>${fmtDate(p.date)}</td><td>${supplier(p.supplierId)?.name||'—'}</td><td>${p.lines.map(l=>productName(l.productId)).join('، ')}</td><td><b>${money(p.total)}</b></td><td>${money(p.paid)}</td><td>${money(p.total-p.paid)}</td><td>${statusBadge(p.status)}</td><td><button class="btn btn-light btn-sm" data-action="view-purchase" data-id="${p.id}">عرض</button></td></tr>`).join('')}</tbody></table></div></div>`}
function renderCustomers(){return `${pageTitle('العملاء','ملفات العملاء والأرصدة وكشوف الحساب',`<button class="btn btn-light" data-action="export-customers">⇩ تصدير</button><button class="btn btn-primary" data-action="add-customer">＋ إضافة عميل</button>`)}<div class="summary-strip"><div class="summary-item"><span>إجمالي العملاء</span><strong>${data.customers.length-1}</strong></div><div class="summary-item"><span>إجمالي المبيعات</span><strong>${money(data.customers.reduce((a,c)=>a+c.sales,0))}</strong></div><div class="summary-item"><span>مبالغ مستحقة</span><strong>${money(data.customers.reduce((a,c)=>a+c.balance,0))}</strong></div><div class="summary-item"><span>عملاء آجل</span><strong>${data.customers.filter(c=>c.type==='عميل آجل').length}</strong></div></div><div class="card table-card"><div class="card-header"><div class="table-tools">${tableSearch('اسم العميل أو الهاتف')}<select class="select-control filter-select" data-filter="customerType"><option value="">كل الأنواع</option><option value="نقدي">نقدي</option><option value="جملة">جملة</option><option value="محل">محل</option><option value="عميل آجل">عميل آجل</option></select></div></div><div class="table-wrap"><table><thead><tr><th>العميل</th><th>الهاتف</th><th>المنطقة</th><th>النوع</th><th>حد الائتمان</th><th>الرصيد المستحق</th><th>إجمالي المبيعات</th><th>إجراء</th></tr></thead><tbody>${data.customers.filter(c=>c.id!=='c-cash'&&c.status!=='غير نشط'&&(!searchTerm||[c.name,c.phone,c.code,c.area].join(' ').includes(searchTerm))&&(!filters.customerType||c.type===filters.customerType)).map(c=>`<tr><td><div class="table-product"><div class="product-avatar">${initials(c.name)}</div><div><strong>${c.name}</strong><span>${c.code}</span></div></div></td><td>${c.phone}</td><td>${c.area}</td><td>${c.type}</td><td>${money(c.credit)}</td><td>${c.balance?`<b class="stat-color">${money(c.balance)}</b>`:'<span class="badge badge-success">مسدد</span>'}</td><td>${money(c.sales)}</td><td><div class="row-actions"><button class="btn btn-light btn-sm" data-action="customer-statement" data-id="${c.id}">كشف الحساب</button><button class="btn btn-light btn-sm btn-icon" data-action="edit-customer" data-id="${c.id}">✎</button><button class="btn btn-danger btn-sm btn-icon" title="حذف" data-action="delete-customer" data-id="${c.id}">🗑️</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function renderSuppliers(){return `${pageTitle('الموردون','إدارة الموردين وأرصدة الحسابات والمشتريات',`<button class="btn btn-primary" data-action="add-supplier">＋ إضافة مورد</button>`)}<div class="summary-strip"><div class="summary-item"><span>عدد الموردين</span><strong>${data.suppliers.filter(s=>s.status!=='غير نشط').length}</strong></div><div class="summary-item"><span>إجمالي المشتريات</span><strong>${money(data.suppliers.reduce((a,s)=>a+s.purchases,0))}</strong></div><div class="summary-item"><span>المستحق للموردين</span><strong>${money(data.suppliers.reduce((a,s)=>a+s.balance,0))}</strong></div><div class="summary-item"><span>المدفوعات</span><strong>${money(data.suppliers.reduce((a,s)=>a+s.payments,0))}</strong></div></div><div class="card table-card"><div class="card-header"><div class="table-tools">${tableSearch('اسم المورد أو الهاتف')}</div></div><div class="table-wrap"><table><thead><tr><th>المورد</th><th>الهاتف</th><th>العنوان</th><th>المشتريات</th><th>المدفوعات</th><th>الرصيد</th><th>إجراء</th></tr></thead><tbody>${data.suppliers.filter(s=>s.status!=='غير نشط'&&(!searchTerm||[s.name,s.phone,s.code].join(' ').includes(searchTerm))).map(s=>`<tr><td><div class="table-product"><div class="product-avatar" style="background:#f1eaff;color:var(--violet)">${initials(s.name)}</div><div><strong>${s.name}</strong><span>${s.code}</span></div></div></td><td>${s.phone}</td><td>${s.address}</td><td>${money(s.purchases)}</td><td>${money(s.payments)}</td><td>${s.balance?`<b class="stat-color">${money(s.balance)}</b>`:'<span class="badge badge-success">لا يوجد</span>'}</td><td><div class="row-actions"><button class="btn btn-light btn-sm" data-action="supplier-statement" data-id="${s.id}">كشف الحساب</button><button class="btn btn-light btn-sm btn-icon" title="تعديل" data-action="edit-supplier" data-id="${s.id}">✎</button><button class="btn btn-danger btn-sm btn-icon" title="حذف" data-action="delete-supplier" data-id="${s.id}">🗑️</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function renderAssets(){return `${pageTitle('الطبالي والصناديق','متابعة الأصول القابلة للإرجاع مع العملاء والسيارات',`<button class="btn btn-primary" data-action="asset-movement">＋ حركة أصول</button>`)}<div class="summary-strip">${data.assets.map(a=>`<div class="summary-item"><span>${a.type}</span><strong>${num(a.total)} <span class="muted small">إجمالي</span></strong><small class="muted">${num(a.withCustomers)} مع العملاء</small></div>`).join('')}</div><div class="two-col"><div class="card table-card"><div class="card-header"><h3>أرصدة الأصول حسب النوع</h3></div><div class="table-wrap"><table><thead><tr><th>نوع الأصل</th><th>الإجمالي</th><th>متاح بالمستودع</th><th>مع العملاء</th><th>نسبة الإرجاع</th></tr></thead><tbody>${data.assets.map(a=>`<tr><td><b>${a.type}</b></td><td>${num(a.total)}</td><td>${num(a.available)}</td><td>${num(a.withCustomers)}</td><td><div class="progress" style="width:100px"><i style="width:${Math.max(3,100-a.withCustomers/a.total*100)}%"></i></div></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-header"><h3>أكثر العملاء احتفاظًا بالأصول</h3></div><div class="card-body">${data.customers.slice(0,3).map((c,i)=>`<div class="stock-row" style="padding:9px 0;border-bottom:1px solid var(--line)"><div class="product-avatar">${i+1}</div><div class="stock-info"><strong>${c.name}</strong><span>${[10,7,4][i]} طبالي · ${[8,5,3][i]} صناديق</span></div><b>${[18,12,7][i]}</b></div>`).join('')}</div></div></div>`}
function renderPayments(){return `${pageTitle('المدفوعات','تحصيلات العملاء ودفعات الموردين والحركة النقدية',`<button class="btn btn-primary" data-action="add-payment">＋ تسجيل دفعة</button>`)}<div class="summary-strip"><div class="summary-item"><span>تحصيلات العملاء</span><strong>${money(data.customers.reduce((a,c)=>a+c.payments,0))}</strong></div><div class="summary-item"><span>دفعات الموردين</span><strong>${money(data.suppliers.reduce((a,s)=>a+s.payments,0))}</strong></div><div class="summary-item"><span>دفعات اليوم</span><strong>${data.payments.filter(p=>p.date===today()).length}</strong></div><div class="summary-item"><span>الرصيد النقدي</span><strong>${money(58240)}</strong></div></div><div class="card table-card"><div class="card-header"><h3>آخر المدفوعات</h3><div class="table-tools">${tableSearch('رقم السند أو الطرف')}<select class="select-control filter-select"><option>كل العمليات</option><option>تحصيل عميل</option><option>دفعة مورد</option></select></div></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>نوع الحركة</th><th>الطرف</th><th>طريقة الدفع</th><th>المبلغ</th><th>البيان</th></tr></thead><tbody>${data.payments.map(p=>`<tr><td>${fmtDate(p.date)}</td><td>${p.partyType==='customer'?'<span class="badge badge-success">تحصيل عميل</span>':'<span class="badge badge-blue">دفعة مورد</span>'}</td><td>${p.partyType==='customer'?customer(p.partyId)?.name:supplier(p.partyId)?.name}</td><td>${p.method}</td><td><b>${money(p.amount)}</b></td><td>${p.note||'—'}</td></tr>`).join('')}</tbody></table></div></div>`}
function renderExpenses(){const list=data.expenses.filter(e=>(!searchTerm||[e.type,e.person,e.note].join(' ').toLowerCase().includes(searchTerm.toLowerCase()))&&(!filters.expenseType||e.type===filters.expenseType));return `${pageTitle('المصروفات','تسجيل ومتابعة المصروفات التشغيلية',`<button class="btn btn-primary" data-action="add-expense">＋ إضافة مصروف</button>`)}<div class="summary-strip"><div class="summary-item"><span>إجمالي المصروفات</span><strong>${money(data.expenses.reduce((a,e)=>a+e.amount,0))}</strong></div><div class="summary-item"><span>وقود</span><strong>${money(data.expenses.filter(e=>e.type==='وقود').reduce((a,e)=>a+e.amount,0))}</strong></div><div class="summary-item"><span>صيانة</span><strong>${money(data.expenses.filter(e=>e.type==='صيانة').reduce((a,e)=>a+e.amount,0))}</strong></div><div class="summary-item"><span>عدد العمليات</span><strong>${list.length}</strong></div></div><div class="card table-card"><div class="card-header"><h3>سجل المصروفات</h3><div class="table-tools">${tableSearch('بحث في المصروفات')}<select class="select-control filter-select" data-filter="expenseType"><option value="">كل الأنواع</option><option value="وقود">وقود</option><option value="صيانة">صيانة</option><option value="نقل">نقل</option><option value="رواتب">رواتب</option><option value="أخرى">أخرى</option></select></div></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>النوع</th><th>المبلغ</th><th>المسؤول</th><th>الوصف</th><th>إجراء</th></tr></thead><tbody>${list.map(e=>`<tr><td>${fmtDate(e.date)}</td><td><span class="badge badge-warning">${e.type}</span></td><td><b>${money(e.amount)}</b></td><td>${e.person}</td><td>${e.note}</td><td><div class="row-actions"><button class="btn btn-light btn-sm btn-icon" title="تعديل" data-action="edit-expense" data-id="${e.id}">✎</button><button class="btn btn-danger btn-sm btn-icon" title="حذف" data-action="delete-expense" data-id="${e.id}">🗑️</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد مصروفات.</td></tr>'}</tbody></table></div></div>`}
function renderReports(){
  const reportData=activeReport==='sales'?data.sales:activeReport==='purchases'?data.purchases:data.products;
  const stale=data.products.filter(p=>!data.movements.some(m=>m.productId===p.id&&String(m.date||'').slice(0,10)>=new Date(Date.now()-30*86400000).toISOString().slice(0,10))).length;
  const returnValue=sum(data.returns||[],'amount'), salesValue=sum(data.sales,'total'), returnRate=salesValue?returnValue/salesValue*100:0;
  return `${pageTitle('التقارير','تقارير تشغيلية ومالية تساعدك على اتخاذ القرار',`<button class="btn btn-light" data-action="print-report">⎙ طباعة</button><button class="btn btn-primary" data-action="export-json">⇩ تصدير التقرير</button>`)}<div class="report-tabs">${[['sales','المبيعات'],['purchases','المشتريات'],['inventory','المخزون'],['routes','الجولات'],['customers','مبيعات العملاء'],['top','الأكثر مبيعًا'],['damaged','التالف']].map(([k,t])=>`<button class="report-chip ${activeReport===k?'active':''}" data-report="${k}">${t}</button>`).join('')}</div><div class="card" style="margin-bottom:17px"><div class="card-body"><div class="form-grid three"><div class="field"><label>من تاريخ</label><input class="input-control" type="date" value="${filters.reportFrom||''}" data-filter="reportFrom" /></div><div class="field"><label>إلى تاريخ</label><input class="input-control" type="date" value="${filters.reportTo||today()}" data-filter="reportTo" /></div><div class="field"><label>الصنف / الطرف</label><select class="select-control" data-filter="reportProduct"><option value="">الكل</option>${data.products.map(p=>`<option value="${p.id}" ${filters.reportProduct===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div></div></div></div><div class="two-col"><div class="card table-card"><div class="card-header"><h3>${activeReport==='sales'?'تقرير المبيعات':activeReport==='purchases'?'تقرير المشتريات':activeReport==='inventory'?'تقرير المخزون':'ملخص التقرير'}</h3><span class="muted small">الفترة المحددة</span></div><div class="table-wrap"><table><thead><tr>${activeReport==='inventory'?'<th>الصنف</th><th>الرصيد</th><th>قيمة الشراء</th><th>الحد الأدنى</th><th>الحالة</th>':'<th>المرجع</th><th>التاريخ</th><th>الطرف</th><th>الإجمالي</th><th>المدفوع</th>'}</tr></thead><tbody>${activeReport==='inventory'?data.products.map(p=>`<tr><td>${p.name}</td><td>${num(p.stock)} ${p.unit}</td><td>${money(p.stock*p.buy)}</td><td>${num(p.min)}</td><td>${p.stock<=p.min?'<span class="badge badge-danger">منخفض</span>':'<span class="badge badge-success">جيد</span>'}</td></tr>`).join(''):reportData.map(x=>`<tr><td>${x.number||'—'}</td><td>${fmtDate(x.date)}</td><td>${x.customerId?customer(x.customerId)?.name:supplier(x.supplierId)?.name||'—'}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-header"><h3>مؤشرات الأداء</h3></div><div class="card-body"><div class="stock-list"><div class="stock-row"><div class="metric-icon">↗</div><div class="stock-info"><strong>هامش الربح التقريبي</strong><span>قبل المصروفات والتالف</span></div><b>${money(totalSales()-data.purchases.reduce((a,p)=>a+p.total,0))}</b></div><div class="stock-row"><div class="metric-icon">▱</div><div class="stock-info"><strong>نسبة إغلاق الجولات</strong><span>من إجمالي الجولات</span></div><b>${data.routes.length?Math.round(data.routes.filter(r=>r.status==='مغلقة').length/data.routes.length*100):0}%</b></div><div class="stock-row"><div class="metric-icon">!</div><div class="stock-info"><strong>أصناف راكدة</strong><span>لم تتحرك خلال 30 يوم</span></div><b>${stale}</b></div><div class="stock-row"><div class="metric-icon">↩</div><div class="stock-info"><strong>نسبة المرتجعات</strong><span>من إجمالي المبيعات</span></div><b>${returnRate.toFixed(1)}%</b></div></div></div></div></div>`;
}
function renderStocktake(){return `${pageTitle('جرد المخزون','مطابقة الرصيد الفعلي مع رصيد النظام وتسجيل التسويات',`<button class="btn btn-primary" data-action="new-stocktake">＋ بدء جرد جديد</button>`)}<div class="summary-strip"><div class="summary-item"><span>آخر جرد</span><strong>${data.stocktakes.length?fmtDate(data.stocktakes[0].date):'لم يبدأ'}</strong></div><div class="summary-item"><span>أصناف تمت مطابقتها</span><strong>${data.stocktakes[0]?.lines?.length||0}</strong></div><div class="summary-item"><span>فروقات تحتاج مراجعة</span><strong class="stat-color">${data.stocktakes[0]?.lines?.filter(x=>x.diff).length||0}</strong></div><div class="summary-item"><span>تسويات هذا الشهر</span><strong>0</strong></div></div><div class="card table-card"><div class="card-header"><h3>الجرد النشط</h3><span class="badge badge-warning">مسودة</span></div><div class="table-wrap"><table><thead><tr><th>الصنف</th><th>رصيد النظام</th><th>الكمية الفعلية</th><th>الفرق</th><th>سبب الفرق</th></tr></thead><tbody>${data.products.map(p=>`<tr><td><div class="table-product"><div class="product-avatar">${initials(p.name)}</div><div><strong>${p.name}</strong><span>${p.sku}</span></div></div></td><td>${num(p.stock)} ${p.unit}</td><td><input class="input-control stock-count" style="width:95px" type="number" min="0" value="${p.stock}" data-id="${p.id}" /></td><td><span class="badge badge-neutral" data-diff="${p.id}">0</span></td><td><input class="input-control" style="width:150px" placeholder="سبب الفرق" /></td></tr>`).join('')}</tbody></table></div><div class="card-body" style="display:flex;justify-content:flex-start;gap:8px"><button class="btn btn-primary" data-action="confirm-stocktake">تأكيد الجرد والتسويات</button><button class="btn btn-light" data-action="save-stocktake-draft">حفظ كمسودة</button></div></div>`}
function renderInvoices(){const query=searchTerm.toLowerCase();const sales=data.sales.filter(s=>(!filters.invoiceType||filters.invoiceType==='sales')&&(!query||[s.number,customer(s.customerId)?.name].join(' ').toLowerCase().includes(query)));const purchases=data.purchases.filter(p=>(!filters.invoiceType||filters.invoiceType==='purchases')&&(!query||[p.number,supplier(p.supplierId)?.name].join(' ').toLowerCase().includes(query)));return `${pageTitle('الفواتير','معاينة وطباعة جميع فواتير البيع والشراء',`<button class="btn btn-light" data-action="print-invoice-last">⎙ طباعة آخر فاتورة</button><button class="btn btn-primary" data-action="open-sale">＋ فاتورة جديدة</button>`)}<div class="card table-card"><div class="card-header"><div class="table-tools">${tableSearch('رقم الفاتورة أو اسم العميل')}<select class="select-control filter-select" data-filter="invoiceType"><option value="">فواتير البيع والشراء</option><option value="sales">فواتير البيع</option><option value="purchases">فواتير الشراء</option></select></div></div><div class="table-wrap"><table><thead><tr><th>النوع</th><th>رقم الفاتورة</th><th>التاريخ</th><th>الطرف</th><th>الإجمالي</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${sales.map(s=>`<tr><td><span class="badge badge-success">بيع</span></td><td><b>${s.number}</b></td><td>${fmtDate(s.date)}</td><td>${customer(s.customerId)?.name||'—'}</td><td>${money(s.total)}</td><td>${statusBadge(s.total===s.paid?'مدفوعة':'آجل')}</td><td><button class="btn btn-light btn-sm" data-action="view-invoice" data-id="${s.id}">معاينة وطباعة</button></td></tr>`).join('')}${purchases.map(p=>`<tr><td><span class="badge badge-blue">شراء</span></td><td><b>${p.number}</b></td><td>${fmtDate(p.date)}</td><td>${supplier(p.supplierId)?.name||'—'}</td><td>${money(p.total)}</td><td>${statusBadge(p.status)}</td><td><button class="btn btn-light btn-sm" data-action="view-purchase" data-id="${p.id}">عرض</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد فواتير مطابقة.</td></tr>'}</tbody></table></div></div>`}
function renderUsers(){return `${pageTitle('المستخدمون والصلاحيات','إدارة المستخدمين والأدوار داخل النظام',`<button class="btn btn-primary" data-action="add-user">＋ إضافة مستخدم</button>`)}<div class="two-col"><div class="card table-card"><div class="card-header"><h3>المستخدمون</h3><span class="muted small">صلاحيات تجريبية للواجهة</span></div><div class="table-wrap"><table><thead><tr><th>المستخدم</th><th>الدور</th><th>الهاتف</th><th>الحالة</th><th></th></tr></thead><tbody>${data.users.map(u=>`<tr><td><div class="table-product"><div class="avatar">${initials(u.name)}</div><div><strong>${u.name}</strong><span>${u.id}</span></div></div></td><td>${u.role}</td><td>${u.phone}</td><td>${statusBadge(u.status)}</td><td><button class="btn btn-light btn-sm" data-action="edit-user" data-id="${u.id}">تعديل</button></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-header"><h3>سجل النشاط</h3></div><div class="card-body activity-list">${data.activity.slice(0,8).map(a=>`<div class="activity-row"><div class="activity-avatar">${initials(a.user)}</div><div><strong>${a.action}</strong><span>${a.user} · ${a.detail}</span><span>${fmtDateTime(a.date)} · ${a.ref}</span></div></div>`).join('')}</div></div></div>`}
function catalogRows(type){const rows=type==='categories'?data.categories:type==='units'?data.units:data.departments;return rows.filter(row=>row.status!=='غير نشط').filter(row=>!searchTerm||String(row.name).toLowerCase().includes(searchTerm.toLowerCase())).map(row=>`<tr><td><b>${esc(row.name)}</b></td><td>${statusBadge(row.status||'نشط')}</td><td><div class="row-actions"><button class="btn btn-light btn-sm btn-icon" data-action="edit-catalog" data-catalog-type="${type}" data-id="${row.id}">✎</button><button class="btn btn-danger btn-sm btn-icon" data-action="delete-catalog" data-catalog-type="${type}" data-id="${row.id}">🗑️</button></div></td></tr>`).join('')||'<tr><td colspan="3" class="empty">لا توجد سجلات</td></tr>'}
function catalogForm(type,row={}){openModal(row.id?'تعديل السجل':'إضافة سجل',`<form data-form="catalog" data-catalog-type="${type}" data-id="${row.id||''}"><div class="field"><label>${type==='categories'?'اسم التصنيف':type==='units'?'اسم الوحدة':'اسم القسم'} <i class="required">*</i></label><input class="input-control" name="name" required value="${esc(row.name)}" /></div><div class="field" style="margin-top:12px"><label>الحالة</label><select class="select-control" name="status"><option ${row.status!=='غير نشط'?'selected':''}>نشط</option><option ${row.status==='غير نشط'?'selected':''}>غير نشط</option></select></div></form>`,formButtons('إلغاء',row.id?'حفظ التعديل':'إضافة'))}
function renderSettings(){
  const tabs=[['company','بيانات الشركة'],['departments','الأقسام'],['catalogs','الوحدات والتصنيفات'],['backup','النسخ الاحتياطي'],['data','إدارة البيانات']];
  const menu=tabs.map(([key,label])=>`<button class="${activeSettingsTab===key?'active':''}" data-action="settings-tab" data-tab="${key}">${label}</button>`).join('');
  let body='';
  if(activeSettingsTab==='company') body=`<div class="card-header"><h3>بيانات شركة السريحي</h3></div><div class="card-body"><div class="form-grid"><div class="field"><label>اسم الشركة</label><input class="input-control" name="company" value="${esc(data.meta.company)}" /></div><div class="field"><label>اسم النظام</label><input class="input-control" value="السريحي ERP" readonly /></div><div class="field"><label>العملة</label><select class="select-control" id="currencySetting" data-setting="currency">${Object.entries(currencyOptions).map(([code,label])=>`<option value="${code}" ${data.meta.currency===code?'selected':''}>${code} — ${label}</option>`).join('')}</select></div><div class="field"><label>الضريبة</label><select class="select-control" data-setting="tax"><option value="false" ${!data.meta.taxEnabled?'selected':''}>غير مفعلة</option><option value="true" ${data.meta.taxEnabled?'selected':''}>مفعلة</option></select></div></div><div class="actions" style="margin-top:18px"><button class="btn btn-primary" data-action="save-settings">حفظ بيانات الشركة</button></div></div>`;
  if(activeSettingsTab==='departments') body=`<div class="card-header"><h3>الأقسام</h3><div class="actions">${tableSearch('بحث في الأقسام')}<button class="btn btn-primary btn-sm" data-action="add-catalog" data-catalog-type="departments">＋ إضافة قسم</button></div></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${catalogRows('departments')}</tbody></table></div>`;
  if(activeSettingsTab==='catalogs'){const isCat=activeCatalogTab==='categories';body=`<div class="card-header"><h3>الوحدات والتصنيفات</h3></div><div class="card-body"><div class="tab-bar"><button class="tab-btn ${isCat?'active':''}" data-action="catalog-tab" data-tab="categories">التصنيفات</button><button class="tab-btn ${!isCat?'active':''}" data-action="catalog-tab" data-tab="units">الوحدات</button></div><div class="actions" style="margin-bottom:10px">${tableSearch(isCat?'بحث في التصنيفات':'بحث في الوحدات')}<button class="btn btn-primary btn-sm" data-action="add-catalog" data-catalog-type="${activeCatalogTab}">＋ ${isCat?'إضافة تصنيف':'إضافة وحدة'}</button></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${catalogRows(activeCatalogTab)}</tbody></table></div></div>`}
  if(activeSettingsTab==='backup') body=`<div class="card-header"><h3>النسخ الاحتياطي</h3></div><div class="card-body"><p class="muted">تصدير واستيراد جميع Object Stores مع التحقق من الملف قبل الاستعادة.</p><div class="actions"><button class="btn btn-primary" data-action="export-json">🟢 تصدير نسخة احتياطية</button><button class="btn btn-light" data-action="import-json">🔵 استيراد نسخة احتياطية</button></div></div>`;
  if(activeSettingsTab==='data') body=`<div class="card-header"><h3>إدارة البيانات</h3></div><div class="card-body"><p class="muted">بيانات الاختبار اختيارية ولا يتم تحميلها عند التهيئة الجديدة.</p><div class="actions"><button class="btn btn-light" data-action="load-demo-data">🟢 تحميل بيانات تجريبية</button><button class="btn btn-light" data-action="delete-demo-data">🟠 حذف البيانات التجريبية</button><button class="btn btn-danger" data-action="delete-operational-data">🔴 حذف البيانات التشغيلية</button><button class="btn btn-danger" data-action="reset-system">⚠️ إعادة ضبط النظام بالكامل</button></div></div>`;
  return `${pageTitle('الإعدادات','إعدادات الشركة والكتالوج والنسخ الاحتياطي',activeSettingsTab==='company'?'<button class="btn btn-primary" data-action="save-settings">حفظ الإعدادات</button>':'')}<div class="settings-grid"><div class="card settings-menu">${menu}</div><div class="card">${body}</div></div>`;
}

const productOptions = (selected='') => activeProducts().map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${p.name} — ${p.sku}</option>`).join('');
const customerOptions = (selected='') => data.customers.filter(c=>c.status!=='غير نشط').map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.name}</option>`).join('');
const supplierOptions = (selected='') => data.suppliers.filter(s=>s.status!=='غير نشط').map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${s.name}</option>`).join('');
function openModal(title,body,foot='',wide=false){const m=document.getElementById('modal');m.className=`modal${wide?' wide':''}`;m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close-modal" data-action="close-modal">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;decorateNumericContent(m);document.getElementById('modalBackdrop').classList.add('open')}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('open');currentLineItems=[]}
function formButtons(cancel='إلغاء',submit='حفظ'){return `<button class="btn btn-light" data-action="close-modal">${cancel}</button><button class="btn btn-primary" type="button" data-action="submit-modal">${submit}</button>`}
function productForm(p={}){openModal(p.id?'تعديل بيانات الصنف':'إضافة صنف جديد',`<form data-form="product" data-id="${p.id||''}"><div class="form-grid three"><div class="field"><label>كود الصنف <i class="required">*</i></label><input class="input-control" name="sku" required value="${esc(p.sku)}" placeholder="W-002" /></div><div class="field"><label>اسم الصنف <i class="required">*</i></label><input class="input-control" name="name" required value="${esc(p.name)}" placeholder="اسم المنتج" /></div><div class="field"><label>الباركود</label><input class="input-control" name="barcode" value="${esc(p.barcode)}" /></div><div class="field"><label>التصنيف</label><select class="select-control" name="category">${categories.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>النوع</label><select class="select-control" name="type"><option ${p.type==='مشروب'?'selected':''}>مشروب</option><option ${p.type==='أصل قابل للإرجاع'?'selected':''}>أصل قابل للإرجاع</option><option ${p.type==='أخرى'?'selected':''}>أخرى</option></select></div><div class="field"><label>الوحدة الأساسية</label><select class="select-control" name="unit">${units.map(unit=>`<option ${p.unit===unit?'selected':''}>${unit}</option>`).join('')}</select></div><div class="field"><label>عدد القطع في الوحدة</label><input class="input-control" name="pack" type="number" min="1" value="${p.pack||1}" /></div><div class="field"><label>سعر الشراء</label><input class="input-control" name="buy" type="number" min="0" step=".01" value="${p.buy||0}" /></div><div class="field"><label>سعر البيع</label><input class="input-control" name="sell" type="number" min="0" step=".01" value="${p.sell||0}" /></div><div class="field"><label>سعر الجملة</label><input class="input-control" name="wholesale" type="number" min="0" step=".01" value="${p.wholesale||0}" /></div><div class="field"><label>الحد الأدنى</label><input class="input-control" name="min" type="number" min="0" value="${p.min||0}" /></div><div class="field"><label>الحد الأقصى</label><input class="input-control" name="max" type="number" min="0" value="${p.max||0}" /></div><div class="field"><label>المنطقة</label><select class="select-control" name="zone">${['A','B','C','D','E','F','G'].map(z=>`<option ${p.zone===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>رقم الرف</label><input class="input-control" name="rack" value="${esc(p.rack)}" placeholder="A01" /></div><div class="field"><label>الشركة المصنعة</label><input class="input-control" name="manufacturer" value="${esc(p.manufacturer)}" /></div>${p.id?'':'<div class="field"><label>الرصيد الافتتاحي</label><input class="input-control" name="stock" type="number" min="0" value="0" /></div>'}</div></form>`,formButtons('إلغاء',p.id?'حفظ التعديل':'إضافة الصنف'))}
function customerForm(c={}){openModal(c.id?'تعديل بيانات العميل':'إضافة عميل جديد',`<form data-form="customer" data-id="${c.id||''}"><div class="form-grid"><div class="field"><label>رقم العميل</label><input class="input-control" name="code" value="${c.code||'CUS-'+String(data.customers.length+1).padStart(3,'0')}" required /></div><div class="field"><label>اسم العميل <i class="required">*</i></label><input class="input-control" name="name" value="${esc(c.name)}" required /></div><div class="field"><label>الهاتف</label><input class="input-control" name="phone" value="${esc(c.phone)}" /></div><div class="field"><label>المنطقة</label><input class="input-control" name="area" value="${esc(c.area)}" /></div><div class="field"><label>العنوان</label><input class="input-control" name="address" value="${esc(c.address)}" /></div><div class="field"><label>نوع العميل</label><select class="select-control" name="type">${['نقدي','جملة','محل','موزع','عميل آجل'].map(x=>`<option ${c.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>حد الائتمان</label><input class="input-control" name="credit" type="number" min="0" value="${c.credit||0}" /></div></div></form>`,formButtons('إلغاء',c.id?'حفظ التعديل':'إضافة العميل'))}
function supplierForm(s={}){openModal(s.id?'تعديل بيانات المورد':'إضافة مورد جديد',`<form data-form="supplier" data-id="${s.id||''}"><div class="form-grid"><div class="field"><label>رقم المورد</label><input class="input-control" name="code" value="${s.code||'SUP-'+String(data.suppliers.length+1).padStart(3,'0')}" required /></div><div class="field"><label>اسم المورد <i class="required">*</i></label><input class="input-control" name="name" value="${esc(s.name)}" required /></div><div class="field"><label>الهاتف</label><input class="input-control" name="phone" value="${esc(s.phone)}" /></div><div class="field"><label>العنوان</label><input class="input-control" name="address" value="${esc(s.address)}" /></div></div></form>`,formButtons('إلغاء',s.id?'حفظ التعديل':'إضافة المورد'))}
function vehicleForm(v={}){openModal(v.id?'تعديل السيارة':'إضافة سيارة',`<form data-form="vehicle" data-id="${v.id||''}"><div class="form-grid"><div class="field"><label>اسم السيارة <i class="required">*</i></label><input class="input-control" name="code" value="${esc(v.code)}" required placeholder="سيارة 04" /></div><div class="field"><label>رقم اللوحة</label><input class="input-control" name="plate" value="${esc(v.plate)}" /></div><div class="field"><label>السائق</label><select class="select-control" name="driver"><option value="">بدون سائق</option>${data.drivers.filter(row=>row.status!=='موقوف').map(row=>`<option value="${esc(row.name)}" ${v.driver===row.name?'selected':''}>${esc(row.name)}</option>`).join('')}</select></div><div class="field"><label>مندوب المبيعات</label><select class="select-control" name="seller"><option value="">بدون مندوب</option>${data.salesRepresentatives.filter(row=>row.status!=='موقوف').map(row=>`<option value="${esc(row.name)}" ${v.seller===row.name?'selected':''}>${esc(row.name)}</option>`).join('')}</select></div><div class="field"><label>الحالة</label><select class="select-control" name="status"><option ${v.status==='متاحة'?'selected':''}>متاحة</option><option ${v.status==='صيانة'?'selected':''}>صيانة</option><option ${v.status==='مغلقة'?'selected':''}>مغلقة</option></select></div></div></form>`,formButtons('إلغاء',v.id?'حفظ':'إضافة السيارة'))}
function personForm(type,row={}){const isDriver=type==='driver';openModal(isDriver?(row.id?'تعديل سائق':'إضافة سائق'):(row.id?'تعديل مندوب':'إضافة مندوب'),`<form data-form="${isDriver?'driver':'representative'}" data-id="${row.id||''}"><div class="form-grid"><div class="field"><label>الاسم <i class="required">*</i></label><input class="input-control" name="name" required value="${esc(row.name)}" /></div><div class="field"><label>الكود</label><input class="input-control" name="code" value="${esc(row.code)}" placeholder="${isDriver?'DRV':'REP'}-001" /></div><div class="field"><label>الهاتف</label><input class="input-control" name="phone" value="${esc(row.phone)}" /></div><div class="field"><label>الحالة</label><select class="select-control" name="status"><option ${row.status!=='موقوف'?'selected':''}>نشط</option><option ${row.status==='موقوف'?'selected':''}>موقوف</option></select></div></div></form>`,formButtons('إلغاء',row.id?'حفظ التعديل':'حفظ'))}
function routeForm(){openModal('إنشاء جولة بيع جديدة',`<form data-form="route"><div class="form-grid"><div class="field"><label>رقم الجولة</label><input class="input-control" name="code" value="RT-${String(data.meta.nextRoute).padStart(4,'0')}" required /></div><div class="field"><label>التاريخ</label><input class="input-control" type="date" name="date" value="${today()}" required /></div><div class="field"><label>السيارة <i class="required">*</i></label><select class="select-control" name="vehicleId" required>${data.vehicles.filter(v=>v.status==='متاحة').map(v=>`<option value="${v.id}">${v.code} — ${v.plate}</option>`).join('')}</select></div><div class="field"><label>المنطقة</label><input class="input-control" name="area" placeholder="شرق الرياض" /></div><div class="field"><label>وقت الخروج</label><input class="input-control" name="outTime" type="time" value="07:30" /></div><div class="field"><label>ملاحظات</label><input class="input-control" name="notes" /></div></div><p class="muted small" style="margin:15px 0 0">بعد إنشاء الجولة، استخدم زر «تحميل» لنقل الأصناف من المستودع إلى السيارة.</p></form>`,formButtons('إلغاء','إنشاء الجولة'))}
function zoneForm(){openModal('إضافة منطقة تخزين',`<form data-form="zone"><div class="form-grid"><div class="field"><label>رمز المنطقة <i class="required">*</i></label><input class="input-control" name="code" required placeholder="H" /></div><div class="field"><label>اسم المنطقة</label><input class="input-control" name="name" placeholder="منطقة H" /></div><div class="field"><label>نوع التخزين</label><select class="select-control" name="storageType"><option>عام</option><option>تبريد</option><option>أصول قابلة للإرجاع</option></select></div><div class="field"><label>الحالة</label><select class="select-control" name="status"><option>نشط</option><option>موقوف</option></select></div><div class="field full"><label>الوصف</label><textarea class="textarea-control" name="description"></textarea></div></div></form>`,formButtons('إلغاء','إضافة المنطقة'))}
function lineEditor(type='sale',initial=[]){currentLineItems=initial.length?initial:[{productId:data.products[0]?.id,qty:1,price:data.products[0]?.sell||0}];const isPurchase=type==='purchase';openModal(isPurchase?'فاتورة شراء جديدة':'فاتورة بيع جديدة',`<form data-form="${type}"><div class="form-grid"><div class="field"><label>${isPurchase?'المورد':'العميل'} <i class="required">*</i></label><select class="select-control" name="partyId" required>${isPurchase?supplierOptions():customerOptions()}</select></div><div class="field"><label>التاريخ</label><input class="input-control" type="date" name="date" value="${today()}" /></div><div class="field"><label>طريقة الدفع</label><select class="select-control" name="method"><option>نقد</option><option>تحويل</option><option>آجل</option><option>دفعة جزئية</option></select></div><div class="field"><label>المبلغ المدفوع</label><input class="input-control" type="number" name="paid" min="0" value="0" /></div></div><div style="margin-top:20px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><b>الأصناف</b><button type="button" class="btn btn-light btn-sm" data-action="add-line" data-type="${type}">＋ إضافة صنف</button></div><div class="line-items" id="lineItems"><div class="line-item header"><span>الصنف</span><span>الكمية</span><span>السعر</span><span>الإجمالي</span><span></span></div>${lineRows(type)}</div></div><div class="totals-box" id="lineTotals">${lineTotals()}</div></form>`,formButtons('إلغاء',isPurchase?'حفظ واستلام':'تأكيد البيع'),true)}
function lineRows(type){const isPurchase=type==='purchase';return currentLineItems.map((l,i)=>`<div class="line-item" data-line="${i}"><select class="select-control line-product">${productOptions(l.productId)}</select><input class="input-control line-qty" type="number" min="1" value="${l.qty}" /><input class="input-control line-price" type="number" min="0" step=".01" value="${l.price||0}" /><span class="line-total">${money((l.qty||0)*(l.price||0))}</span><button type="button" class="remove-line" data-action="remove-line" data-index="${i}">×</button></div>`).join('')}
function lineTotals(){const subtotal=currentLineItems.reduce((a,l)=>a+(l.qty||0)*(l.price||0),0);return `<div class="total-row"><span>المجموع الفرعي</span><b>${money(subtotal)}</b></div><div class="total-row"><span>الخصم</span><span>${money(0)}</span></div><div class="total-row"><span>الضريبة</span><span>${money(0)}</span></div><div class="total-row final"><span>الإجمالي النهائي</span><b>${money(subtotal)}</b></div>`}
function loadForm(r){openModal(`تحميل بضاعة إلى ${r.code}`,`<form data-form="route-load" data-id="${r.id}"><p class="muted small" style="margin-top:0">سيتم خصم الكميات من المستودع وإضافتها إلى رصيد السيارة. هذه البضاعة ليست مباعة.</p><div class="line-items" id="loadLines"><div class="line-item header"><span>الصنف</span><span>المتاح</span><span>الكمية</span><span></span><span></span></div><div class="line-item"><select class="select-control load-product">${productOptions()}</select><span class="muted small load-available">${data.products[0]?.stock||0}</span><input class="input-control load-qty" type="number" min="1" value="1" /><span></span><button type="button" class="remove-line" data-action="add-load-line">＋</button></div></div><div class="muted small" style="margin-top:12px">يمكن تحميل عدة أصناف في نفس الجولة.</div></form>`,formButtons('إلغاء','تأكيد التحميل'))}
function routeSaleForm(r){openModal(`تسجيل بيع من الجولة ${r.code}`,`<form data-form="route-sale" data-id="${r.id}"><div class="form-grid"><div class="field"><label>العميل <i class="required">*</i></label><select class="select-control" name="customerId">${customerOptions()}</select></div><div class="field"><label>التاريخ</label><input class="input-control" type="date" name="date" value="${today()}" /></div><div class="field"><label>طريقة الدفع</label><select class="select-control" name="method"><option>نقد</option><option>تحويل</option><option>آجل</option></select></div><div class="field"><label>المبلغ المدفوع</label><input class="input-control" name="paid" type="number" min="0" value="0" /></div></div><div style="margin-top:18px"><div class="line-items"><div class="line-item header"><span>الصنف</span><span>المتاح</span><span>الكمية المباعة</span><span>السعر</span><span></span></div>${r.loaded.map(x=>{let p=product(x.productId);return `<div class="line-item route-sale-line" data-product="${p.id}"><span class="small"><b>${p.name}</b></span><span class="muted small">${num(routeAvailable(r,p.id))} ${p.unit}</span><input class="input-control route-qty" type="number" min="0" max="${routeAvailable(r,p.id)}" value="0" /><input class="input-control route-price" type="number" min="0" step=".01" value="${p.sell}" /><span></span></div>`}).join('')}</div></div><div class="totals-box"><div class="total-row final"><span>إجمالي البيع</span><b id="routeSaleTotal">${money(0)}</b></div></div></form>`,formButtons('إلغاء','تسجيل البيع'),true)}
function closeRouteForm(r){const rows=(r.loaded||[]).map(x=>{let p=product(x.productId),sold=routeSold(r,p.id);return `<div class="line-item close-line" data-product="${p.id}"><span class="small"><b>${p.name}</b><br><span class="muted">خرج ${x.qty} ${p.unit} · بيع ${sold}</span></span><span class="muted small">المتبقي ${routeAvailable(r,p.id)}</span><input class="input-control return-qty" type="number" min="0" max="${routeAvailable(r,p.id)}" value="${routeAvailable(r,p.id)}" /><select class="select-control loss-type"><option value="">بدون فرق</option><option>تالف</option><option>مفقود</option><option>كسر</option><option>خطأ في التسجيل</option><option>سبب آخر</option></select><input class="input-control loss-qty" type="number" min="0" max="${routeAvailable(r,p.id)}" value="0" /></div>`}).join('');openModal(`إغلاق الجولة ${r.code}`,`<form data-form="close-route" data-id="${r.id}"><div class="card" style="background:var(--warning-soft);border-color:#f0d18f;margin-bottom:15px"><div class="card-body"><b>مراجعة التسوية</b><p class="small" style="margin:4px 0 0">يجب أن تساوي الكمية الخارجة: المباعة + المرتجعة + التالف/المفقود. أي فرق غير مبرر يمنع الإغلاق.</p></div></div><div class="line-items"><div class="line-item header"><span>الصنف</span><span>المتاح</span><span>مرتجع سليم</span><span>نوع الفرق</span><span>كمية الفرق</span></div>${rows}</div><div class="field" style="margin-top:14px"><label>ملاحظات الإغلاق</label><textarea class="textarea-control" name="notes" placeholder="أدخل تفاصيل أي فرق أو ملاحظة..."></textarea></div></form>`,formButtons('إلغاء','تأكيد إغلاق الجولة'),true)}

function showToast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`<span>${type==='success'?'✓':'!'}</span>${message}`;document.getElementById('toastRegion').appendChild(el);setTimeout(()=>el.remove(),3500)}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function exportJSON(){
  try{
    const backup=await db.exportBackup();
    download(`AlSuraishi_Backup_${today()}.json`,JSON.stringify(backup,null,2));
    addActivity('تصدير نسخة احتياطية',`${Object.values(backup.stores).reduce((n,rows)=>n+rows.length,0)} سجل`,'BACKUP');
    save();
    showToast('تم تصدير النسخة الاحتياطية بنجاح');
  }catch(error){console.error(error);showToast('تعذر تصدير النسخة الاحتياطية','error')}
}
function confirmDeleteProduct(id){
  const p=product(id);if(!p)return;
  openModal('تأكيد حذف العنصر',`<div class="card-body"><p>هل أنت متأكد من حذف هذا العنصر؟</p><p class="muted small">سيتم تعطيله مع الاحتفاظ بسجل المخزون والفواتير السابقة.</p></div>`,`<button class="btn btn-light" data-action="close-modal">إلغاء</button><button class="btn btn-danger" data-action="confirm-delete-product" data-id="${id}">حذف</button>`)
}
function confirmDeleteRecord(type,id){
  const lookup={customer, supplier, vehicle, expense:x=>data.expenses.find(e=>e.id===x), driver:x=>data.drivers.find(row=>row.id===x), representative:x=>data.salesRepresentatives.find(row=>row.id===x)}[type], record=lookup?.(id);
  if(!record)return;
  const label=record.name||record.type||'السجل';
  openModal('تأكيد حذف السجل',`<div class="card-body"><p>هل أنت متأكد من حذف <b>${esc(label)}</b>؟</p><p class="muted small">سيتم فحص الارتباطات قبل التنفيذ. إذا كان للسجل تأثير محاسبي سيُعطّل بدل حذفه نهائيًا.</p></div>`,`<button class="btn btn-light" data-action="close-modal">إلغاء</button><button class="btn btn-danger" data-action="confirm-delete-record" data-record-type="${type}" data-id="${id}">حذف</button>`);
}
function confirmDeleteCatalog(type,id){
  const collection=type==='categories'?data.categories:type==='units'?data.units:data.departments,row=collection.find(item=>item.id===id);if(!row)return;
  openModal('تأكيد حذف السجل',`<div class="card-body"><p>هل أنت متأكد من حذف <b>${esc(row.name)}</b>؟</p><p class="muted small">إذا كان التصنيف أو الوحدة مستخدمًا في أصناف سابقة سيتم أرشفته بدل حذف السجل.</p></div>`,`<button class="btn btn-light" data-action="close-modal">إلغاء</button><button class="btn btn-danger" data-action="confirm-delete-catalog" data-catalog-type="${type}" data-id="${id}">حذف</button>`);
}
function deleteCatalog(type,id){
  const collection=type==='categories'?data.categories:type==='units'?data.units:data.departments,row=collection.find(item=>item.id===id);if(!row)return;
  const used=type==='categories'?data.products.some(p=>p.category===row.name):type==='units'?data.products.some(p=>p.unit===row.name):false;
  if(used){row.status='غير نشط';addActivity('أرشفة كتالوج',`${row.name} مستخدم في سجلات سابقة`,id);showToast('لا يمكن حذف السجل المستخدم؛ تم أرشفته بدلًا من كسره','error')}
  else{const index=collection.findIndex(item=>item.id===id);if(index>=0)collection.splice(index,1);addActivity('حذف كتالوج',row.name,id);showToast('تم حذف السجل المحدد')}
  save();closeModal();render();
}
function confirmDeletePayment(id){const row=data.payments.find(item=>item.id===id);if(!row)return;openModal('تأكيد حذف الدفعة',`<div class="card-body"><p>سيتم عكس مبلغ <b>${money(row.amount)}</b> من رصيد الطرف.</p><p class="muted small">هل تريد المتابعة؟</p></div>`,`<button class="btn btn-light" data-action="close-modal">إلغاء</button><button class="btn btn-danger" data-action="confirm-delete-payment" data-id="${id}">حذف</button>`)}
function deletePayment(id){const row=data.payments.find(item=>item.id===id);if(!row)return;const party=row.partyType==='customer'?customer(row.partyId):supplier(row.partyId);if(party)updatePartyBalance(party,{payment:-Number(row.amount||0)},row.partyType);data.payments=data.payments.filter(item=>item.id!==id);addActivity('حذف دفعة',money(row.amount),id);save();closeModal();render();showToast('تم حذف الدفعة وعكس الرصيد')}
function deleteRecord(type,id){
  const record=type==='customer'?customer(id):type==='supplier'?supplier(id):data.expenses.find(e=>e.id===id);
  if(!record)return;
  if(type==='customer'){
    const linked=data.sales.some(s=>s.customerId===id)||data.payments.some(p=>p.partyType==='customer'&&p.partyId===id)||data.returns.some(r=>r.partyType!=='supplier'&&(r.customerId===id||r.party===record.name));
    if(linked){record.status='غير نشط';addActivity('تعطيل عميل',`${record.name} مرتبط بمستندات سابقة`,id);save();closeModal();render();showToast('لا يمكن حذف العميل المرتبط بفواتير؛ تم تحويله إلى غير نشط');return}
    data.customers=data.customers.filter(x=>x.id!==id);
  }else if(type==='supplier'){
    const linked=data.purchases.some(p=>p.supplierId===id)||data.payments.some(p=>p.partyType==='supplier'&&p.partyId===id)||data.returns.some(r=>r.partyType==='supplier'&&(r.supplierId===id||r.party===record.name));
    if(linked){record.status='غير نشط';addActivity('تعطيل مورد',`${record.name} مرتبط بمستندات سابقة`,id);save();closeModal();render();showToast('لا يمكن حذف المورد المرتبط بفواتير؛ تم تحويله إلى غير نشط');return}
    data.suppliers=data.suppliers.filter(x=>x.id!==id);
  }else if(type==='vehicle'){
    const linked=data.routes.some(r=>r.vehicleId===id);
    if(linked){record.status='مغلقة';addActivity('تعطيل سيارة',`${record.code} مرتبطة برحلات سابقة`,id);save();closeModal();render();showToast('لا يمكن حذف السيارة المرتبطة برحلات؛ تم تعطيلها');return}
    data.vehicles=data.vehicles.filter(x=>x.id!==id);
  }else if(type==='driver'){
    const linked=data.vehicles.some(row=>row.driver===record.name)||data.routes.some(row=>row.driver===record.name);
    if(linked){record.status='موقوف';addActivity('تعطيل سائق',`${record.name} مرتبط بسيارات أو رحلات`,id);save();closeModal();render();showToast('لا يمكن حذف السائق المرتبط بعمليات؛ تم إيقافه');return}
    data.drivers=data.drivers.filter(x=>x.id!==id);
  }else if(type==='representative'){
    const linked=data.vehicles.some(row=>row.seller===record.name)||data.sales.some(row=>row.salespersonId===id);
    if(linked){record.status='موقوف';addActivity('تعطيل مندوب',`${record.name} مرتبط بعمليات`,id);save();closeModal();render();showToast('لا يمكن حذف المندوب المرتبط بعمليات؛ تم إيقافه');return}
    data.salesRepresentatives=data.salesRepresentatives.filter(x=>x.id!==id);
  }else{
    data.expenses=data.expenses.filter(x=>x.id!==id);
  }
  const labels={customer:'عميل',supplier:'مورد',vehicle:'سيارة',driver:'سائق',representative:'مندوب',expense:'مصروف'};
  addActivity('حذف سجل',`${labels[type]||'سجل'} · ${label}`,id);save();closeModal();render();showToast('تم حذف السجل المحدد فقط');
}
function importBackup(){
  const input=document.createElement('input');
  input.type='file'; input.accept='.json,application/json';
  input.onchange=()=>{
    const file=input.files?.[0]; if(!file)return;
    const reader=new FileReader();
    reader.onload=()=>{
      try{
        const parsed=JSON.parse(reader.result);
        if(!parsed||parsed.format!=='AlSuraishiERP'||!parsed.stores) throw new Error('invalid');
        const counts=Object.entries(parsed.stores).map(([name,rows])=>`${name}: ${Array.isArray(rows)?rows.length:0}`).filter(x=>!x.endsWith(': 0')).slice(0,10).join(' · ');
        pendingImport=parsed;
        openModal('تأكيد استيراد النسخة الاحتياطية',`<div class="card-body"><p>تم التحقق من نوع النسخة وبنيتها.</p><p class="muted small">${esc(file.name)} · ${counts||'لا توجد سجلات'}</p><p class="muted small">اختر طريقة الاستيراد:</p></div>`,`<button class="btn btn-light" data-action="close-modal">إلغاء</button><button class="btn btn-light" data-action="import-merge">إضافة إلى البيانات الحالية</button><button class="btn btn-primary" data-action="import-replace">استبدال البيانات الحالية</button>`);
      }catch(error){console.error(error);showToast('ملف النسخة الاحتياطية غير صالح أو ليس لنظام السريحي','error')}
    };
    reader.readAsText(file);
  };
  input.click();
}

async function completeImport(mode){
  if(!pendingImport)return;
  try{
    data=await db.importBackup(pendingImport,mode);
    ensureDataModel();
    addActivity('استيراد نسخة احتياطية',mode==='replace'?'استبدال البيانات الحالية':'دمج البيانات','BACKUP');
    pendingImport=null; save(); closeModal(); render(); showToast(mode==='replace'?'تم استبدال البيانات بنجاح':'تمت إضافة بيانات النسخة بنجاح');
  }catch(error){console.error(error);showToast(error.message||'تعذر استيراد النسخة، لم تتغير البيانات الحالية','error')}
}
function saveSettings(){
  const company=document.querySelector('#section-settings input.input-control:not([readonly])')?.value?.trim();
  if(company)data.meta.company=company;
  const tax=document.querySelector('#section-settings select[data-setting="tax"]')?.value||document.querySelectorAll('#section-settings select')[1]?.value;
  if(tax!==undefined)data.meta.taxEnabled=tax==='true';
  save();render();showToast('تم حفظ الإعدادات بنجاح');
}

function removeLegacyStorage(){
  try{
    localStorage.removeItem(STORAGE_KEY);
    for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key?.startsWith(`${STORAGE_KEY}:backup:`))localStorage.removeItem(key)}
  }catch(error){console.error('Unable to clear legacy LocalStorage',error)}
}
function emptyState(){
  return {meta:{company:'شركة السريحي',currency:'د.ت',taxEnabled:false,theme:'light',nextInvoice:1,nextPurchase:1,nextRoute:1},products:[],customers:[],suppliers:[],vehicles:[],routes:[],purchases:[],sales:[],payments:[],expenses:[],returns:[],movements:[],assets:[],stocktakes:[],users:[],activity:[],warehouses:[],warehouseZones:[]};
}
async function loadDemoData(){
  try{
    const preservedMeta={...data.meta};
    data=seedData();
    data.meta={...data.meta,...preservedMeta,demoMode:true,currency:'د.ت'};
    ensureDataModel();
    addActivity('تحميل بيانات تجريبية','تم تحميل مجموعة بيانات اختيارية','DEMO');
    await db.saveSnapshot(data);
    closeModal(); render(); showToast('تم تحميل البيانات التجريبية بنجاح');
  }catch(error){console.error(error);showToast('تعذر تحميل البيانات التجريبية','error')}
}
function deleteDemoData(){
  if(!data.meta?.demoMode){showToast('لا توجد مجموعة بيانات تجريبية محملة بواسطة النظام','error');return}
  typedConfirmation('حذف البيانات التجريبية','سيتم حذف البيانات التجريبية الحالية مع الإبقاء على إعدادات الشركة والواجهة.','احذف','confirm-delete-demo');
}
async function confirmDeleteDemo(){
  try{
    await db.deleteOperationalData();
    removeLegacyStorage();
    data=emptyState(); data.meta.demoMode=false; ensureDataModel();
    await db.saveSnapshot(data);
    await db.add('settings',{id:'migration.localStorage.v1',key:'migration.localStorage.v1',status:'success',completedAt:new Date().toISOString(),source:'demo-delete'});
    closeModal(); render(); showToast('تم حذف البيانات التجريبية بنجاح');
  }catch(error){console.error(error);showToast('تعذر حذف البيانات التجريبية، لم يتم تغيير البيانات','error')}
}
function typedConfirmation(title,description,word,action){
  openModal(title,`<div class="card-body"><p>${description}</p><p class="muted small">اكتب <b dir="ltr">${word}</b> لتفعيل الزر.</p><input class="input-control" id="dangerConfirmation" autocomplete="off" placeholder="${word}" /></div>`,`<button class="btn btn-light" data-action="close-modal">إلغاء</button><button class="btn btn-danger" id="dangerConfirmButton" data-action="${action}" disabled>تنفيذ نهائيًا</button>`);
  const input=document.getElementById('dangerConfirmation'), button=document.getElementById('dangerConfirmButton');
  input?.addEventListener('input',()=>{button.disabled=input.value.trim()!==word});
}
async function deleteOperationalData(){
  try{
    await db.deleteOperationalData();
    removeLegacyStorage();
    data=await db.readState(); ensureDataModel();
    closeModal(); render(); showToast('تم حذف بيانات التشغيل فقط، وبقيت إعدادات الشركة والواجهة');
  }catch(error){console.error(error);showToast('تعذر حذف بيانات التشغيل، لم يتم تغيير قاعدة البيانات','error')}
}
async function resetSystem(){
  try{
    await db.resetSystem(); removeLegacyStorage();
    data=emptyState(); ensureDataModel();
    await db.saveSnapshot(data); await db.add('settings',{id:'migration.localStorage.v1',key:'migration.localStorage.v1',status:'success',completedAt:new Date().toISOString(),source:'reset'}); dbReady=true;
    closeModal(); render(); showToast('تمت إعادة ضبط النظام إلى الحالة الأولى');
  }catch(error){console.error(error);showToast('تعذر إعادة ضبط النظام، لم تكتمل العملية','error')}
}
function openProductMovements(id){const p=product(id),moves=data.movements.filter(m=>m.productId===id);openModal(`حركة الصنف: ${p.name}`,`<div class="summary-strip"><div class="summary-item"><span>الرصيد الحالي</span><strong>${num(p.stock)} ${p.unit}</strong></div><div class="summary-item"><span>عدد الحركات</span><strong>${moves.length}</strong></div><div class="summary-item"><span>قيمة الرصيد</span><strong>${money(p.stock*p.buy)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>نوع الحركة</th><th>من</th><th>إلى</th><th>الكمية</th><th>المرجع</th></tr></thead><tbody>${moves.map(m=>`<tr><td>${fmtDate(m.date)}</td><td>${m.type}</td><td>${m.from}</td><td>${m.to}</td><td class="${m.qty<0?'stat-color':''}">${m.qty>0?'+':''}${num(m.qty)} ${p.unit}</td><td>${m.ref}</td></tr>`).join('')}</tbody></table></div>`,`<button class="btn btn-light" data-action="close-modal">إغلاق</button>`,true)}
function openStatement(type,id){const isC=type==='customer',party=isC?customer(id):supplier(id),docs=isC?data.sales.filter(s=>s.customerId===id):data.purchases.filter(s=>s.supplierId===id);openModal(`كشف حساب: ${party.name}`,`<div class="summary-strip"><div class="summary-item"><span>الرصيد الحالي</span><strong class="stat-color">${money(party.balance)}</strong></div><div class="summary-item"><span>${isC?'إجمالي المبيعات':'إجمالي المشتريات'}</span><strong>${money(isC?party.sales:party.purchases)}</strong></div><div class="summary-item"><span>إجمالي المدفوعات</span><strong>${money(party.payments)}</strong></div><div class="summary-item"><span>الهاتف</span><strong>${party.phone}</strong></div></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>البيان</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead><tbody>${docs.map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${x.number}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.total-x.paid)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد حركات</td></tr>'}</tbody></table></div>`,`<button class="btn btn-light" data-action="close-modal">إغلاق</button>`,true)}
function invoicePreview(s){const c=customer(s.customerId);openModal('معاينة فاتورة البيع',`<div class="print-invoice"><div class="invoice-head"><div><h1>شركة السريحي</h1><p>توزيع وبيع المواد الغذائية والمشروبات</p><p>تونس · الجمهورية التونسية</p></div><div style="text-align:left"><h1>فاتورة بيع</h1><p>رقم: ${s.number}</p><p>التاريخ: ${fmtDate(s.date)}</p></div></div><div class="invoice-meta"><div><span>العميل</span><strong>${c?.name||'—'}</strong></div><div><span>الهاتف</span><strong>${c?.phone||'—'}</strong></div><div><span>طريقة الدفع</span><strong>${s.method}</strong></div></div><table style="min-width:0"><thead><tr><th>#</th><th>الصنف</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${s.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${productName(l.productId)}</td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.total||l.qty*l.price)}</td></tr>`).join('')}</tbody></table><div class="totals-box" style="margin-top:20px"><div class="total-row"><span>المجموع</span><b>${money(s.subtotal)}</b></div><div class="total-row"><span>الخصم</span><b>${money(s.discount||0)}</b></div><div class="total-row final"><span>الإجمالي</span><b>${money(s.total)}</b></div><div class="total-row"><span>المدفوع</span><b>${money(s.paid)}</b></div><div class="total-row"><span>المتبقي</span><b>${money(s.total-s.paid)}</b></div></div></div>`,`<button class="btn btn-light" data-action="close-modal">إغلاق</button><button class="btn btn-primary" data-action="print-modal">⎙ طباعة</button>${s.status==='ملغاة'?'':'<button class="btn btn-danger" data-action="cancel-sale" data-id="'+s.id+'">إلغاء المستند</button>'}`,true)}

function cancelSale(id){
  const s=data.sales.find(x=>x.id===id); if(!s||s.status==='ملغاة')return;
  if(!confirm('سيتم عكس المخزون والحسابات وتسجيل إلغاء المستند. هل تريد المتابعة؟'))return;
  if(s.routeId){const r=route(s.routeId);if(r)r.sold=(r.sold||[]).filter(x=>x.saleId!==s.id)}
  else (s.lines||[]).forEach(line=>{const p=product(line.productId);if(p){p.stock+=Number(line.qty)||0;movement(p.id,Number(line.qty)||0,'عكس بيع ملغى','العميل','المستودع الرئيسي',s.number)}});
  updatePartyBalance(customer(s.customerId),{sale:-Number(s.total||0),payment:-Number(s.paid||0)},'customer');
  s.status='ملغاة'; s.cancelledAt=new Date().toISOString();
  addActivity('إلغاء فاتورة بيع',s.number,s.id); save(); closeModal(); render(); showToast('تم إلغاء الفاتورة وعكس آثارها');
}
function cancelPurchase(id){
  const p=data.purchases.find(x=>x.id===id); if(!p||p.status==='ملغاة')return;
  if(!confirm('سيتم عكس الاستلام والمخزون وحساب المورد. هل تريد المتابعة؟'))return;
  for(const line of p.lines||[]){const productRow=product(line.productId);if(!productRow||Number(productRow.stock||0)<Number(line.qty||0)){showToast(`لا يمكن الإلغاء: المخزون الحالي لا يكفي لعكس ${productName(line.productId)}`,'error');return}}
  (p.lines||[]).forEach(line=>{const productRow=product(line.productId);productRow.stock-=Number(line.qty)||0;movement(productRow.id,-Number(line.qty)||0,'عكس شراء ملغى','المستودع الرئيسي','المورد',p.number)});
  updatePartyBalance(supplier(p.supplierId),{purchase:-Number(p.total||0),payment:-Number(p.paid||0)},'supplier');
  p.status='ملغاة'; p.cancelledAt=new Date().toISOString();
  addActivity('إلغاء فاتورة شراء',p.number,p.id); save(); closeModal(); render(); showToast('تم إلغاء الشراء وعكس آثاره');
}
function syncLineItems(form){return [...form.querySelectorAll('.line-item[data-line]')].map(row=>({productId:row.querySelector('.line-product').value,qty:Number(row.querySelector('.line-qty').value),price:Number(row.querySelector('.line-price').value)}));}
function handleAction(action,el){
  const id=el?.dataset?.id;
  if(action==='close-modal'){closeModal();return}
  if(action==='confirm-delete-product'){const p=product(id);if(p){p.status='غير نشط';addActivity('تعطيل صنف',p.name,p.sku);save();closeModal();render();showToast('تم تعطيل الصنف مع الاحتفاظ بتاريخه')}return}
  if(action==='submit-modal'){const form=document.querySelector('#modal [data-form]');if(form&&!form.checkValidity()){form.reportValidity();return}if(form)submitForm(form);return}
  if(action==='refresh'){render();showToast('تم تحديث البيانات');return}
  if(action==='add-product'){productForm();return}
  if(action==='edit-product'){productForm(product(id));return}
  if(action==='delete-product'){confirmDeleteProduct(id);return}
  if(action==='delete-customer'){confirmDeleteRecord('customer',id);return}
  if(action==='delete-supplier'){confirmDeleteRecord('supplier',id);return}
  if(action==='delete-expense'){confirmDeleteRecord('expense',id);return}
  if(action==='confirm-delete-record'){deleteRecord(el.dataset.recordType,id);return}
  if(action==='confirm-delete-catalog'){deleteCatalog(el.dataset.catalogType,id);return}
  if(action==='confirm-delete-payment'){deletePayment(id);return}
  if(action==='product-movements'){openProductMovements(id);return}
  if(action==='add-customer'){customerForm();return}
  if(action==='edit-customer'){customerForm(customer(id));return}
  if(action==='customer-statement'){openStatement('customer',id);return}
  if(action==='add-supplier'){supplierForm();return}
  if(action==='edit-supplier'){supplierForm(supplier(id));return}
  if(action==='supplier-statement'){openStatement('supplier',id);return}
  if(action==='add-vehicle'){vehicleForm();return}
  if(action==='edit-vehicle'){vehicleForm(vehicle(id));return}
  if(action==='delete-vehicle'){confirmDeleteRecord('vehicle',id);return}
  if(action==='add-driver'){personForm('driver');return}
  if(action==='edit-driver'){personForm('driver',data.drivers.find(row=>row.id===id));return}
  if(action==='delete-driver'){confirmDeleteRecord('driver',id);return}
  if(action==='add-representative'){personForm('representative');return}
  if(action==='edit-representative'){personForm('representative',data.salesRepresentatives.find(row=>row.id===id));return}
  if(action==='delete-representative'){confirmDeleteRecord('representative',id);return}
  if(action==='add-zone'){zoneForm();return}
  if(action==='add-route'){routeForm();return}
  if(action==='route-load'){loadForm(route(id));return}
  if(action==='route-sale'){routeSaleForm(route(id));return}
  if(action==='close-route'){closeRouteForm(route(id));return}
  if(action==='route-detail'){showRouteDetail(route(id));return}
  if(action==='open-sale'){lineEditorV2('sale');return}
  if(action==='add-purchase'||action==='receive-goods'){lineEditorV2('purchase');return}
  if(action==='add-payment'){paymentForm();return}
  if(action==='edit-payment'){paymentForm(data.payments.find(row=>row.id===id));return}
  if(action==='delete-payment'){confirmDeletePayment(id);return}
  if(action==='add-expense'){expenseForm();return}
  if(action==='edit-expense'){expenseForm(data.expenses.find(row=>row.id===id));return}
  if(action==='add-return'){returnFormV2();return}
  if(action==='asset-movement'){assetForm();return}
  if(action==='add-user'||action==='edit-user'){userForm(action==='edit-user'?data.users.find(x=>x.id===id):{});return}
  if(action==='add-line'){currentLineItems.push({productId:data.products[0]?.id,qty:1,price:el.dataset.type==='purchase'?data.products[0]?.buy:data.products[0]?.sell});rerenderModalLines(el.dataset.type);return}
  if(action==='remove-line'){if(currentLineItems.length>1){currentLineItems.splice(Number(el.dataset.index),1);rerenderModalLines(document.querySelector('[data-form]')?.dataset.form||'sale')}return}
  if(action==='add-load-line'){const cont=document.getElementById('loadLines');const row=cont.querySelector('.line-item:last-child').cloneNode(true);row.querySelector('.load-qty').value=1;row.querySelector('.load-product').selectedIndex=0;row.querySelector('.load-available').textContent=data.products[0]?.stock||0;row.querySelector('[data-action="add-load-line"]').dataset.action='remove-load-line';row.querySelector('[data-action="remove-load-line"]').textContent='×';row.querySelector('[data-action="remove-load-line"]').className='remove-line';cont.appendChild(row);return}
  if(action==='remove-load-line'){el.closest('.line-item').remove();return}
  if(action==='export-json'){exportJSON();return}
  if(action==='export-products'){exportCollection('الأصناف',data.products);return}
  if(action==='export-customers'){exportCollection('العملاء',data.customers);return}
  if(action==='import-json'){importBackup();return}
  if(action==='import-replace'){completeImport('replace');return}
  if(action==='import-merge'){completeImport('merge');return}
  if(action==='delete-operational-data'){typedConfirmation('حذف جميع بيانات التشغيل','سيتم حذف الأصناف والمخزون والعملاء والموردين والفواتير والرحلات والمدفوعات والمصروفات وحركات المخزون نهائيًا.','احذف','confirm-delete-operational');return}
  if(action==='confirm-delete-operational'){deleteOperationalData();return}
  if(action==='reset-system'){typedConfirmation('إعادة ضبط النظام بالكامل','سيتم حذف بيانات التشغيل وإعدادات الشركة وبيانات الاختبار وإعادة النظام إلى حالته الأولى. لا يمكن التراجع عن هذا الإجراء.','إعادة ضبط','confirm-reset-system');return}
  if(action==='confirm-reset-system'){resetSystem();return}
  if(action==='load-demo-data'){loadDemoData();return}
  if(action==='delete-demo-data'){deleteDemoData();return}
  if(action==='confirm-delete-demo'){confirmDeleteDemo();return}
  if(action==='route-filter'){routeStatusFilter=el.dataset.filter||'';render();return}
  if(action==='print-modal'){window.print();return}
  if(action==='view-invoice'){invoicePreview(data.sales.find(x=>x.id===id));return}
  if(action==='view-purchase'){purchasePreview(data.purchases.find(x=>x.id===id));return}
  if(action==='cancel-sale'){cancelSale(id);return}
  if(action==='cancel-purchase'){cancelPurchase(id);return}
  if(action==='new-stocktake'){activeSection='stocktake';render();showToast('تم فتح ورقة جرد جديدة. أدخل الكميات الفعلية ثم احفظها أو اعتمد التسوية');return}
  if(action==='save-stocktake-draft'){saveStocktakeDraft();return}
  if(action==='confirm-stocktake'){confirmStocktake();return}
  if(action==='print-report'){window.print();return}
  if(action==='print-invoice-last'){const s=data.sales[data.sales.length-1];if(s)invoicePreview(s);return}
  if(action==='scan-barcode'){document.getElementById('globalSearch').focus();showToast('أدخل الباركود في البحث ثم اضغط Enter');return}
  if(action==='scan-barcode'){document.getElementById('globalSearch').focus();showToast('أدخل الباركود في البحث ثم اضغط Enter');return}
  if(action==='save-settings'){saveSettings();return}
  if(action==='settings-tab'){activeSettingsTab=el.dataset.tab||'company';searchTerm='';render();return}
  if(action==='catalog-tab'){activeCatalogTab=el.dataset.tab||'categories';searchTerm='';render();return}
  if(action==='add-catalog'){catalogForm(el.dataset.catalogType);return}
  if(action==='edit-catalog'){const collection=el.dataset.catalogType==='categories'?data.categories:el.dataset.catalogType==='units'?data.units:data.departments;catalogForm(el.dataset.catalogType,collection.find(row=>row.id===id));return}
  if(action==='delete-catalog'){confirmDeleteCatalog(el.dataset.catalogType,id);return}
}
function navigateToSection(section){
  if(!navNames[section]) return;
  activeSection=section;
  searchTerm='';
  if(window.matchMedia('(max-width: 768px)').matches) closeMobileSidebar();
  closeModal();
  render();
}
function rerenderModalLines(type){const root=document.querySelector('#lineItems');if(root){root.innerHTML=`<div class="line-item header"><span>الصنف</span><span>الكمية</span><span>السعر</span><span>الإجمالي</span><span></span></div>${lineRows(type)}`;document.getElementById('lineTotals').innerHTML=lineTotals();decorateNumericContent(document.getElementById('modal'))}}
function showRouteDetail(r){openModal(`تفاصيل الجولة ${r.code}`,`<div class="summary-strip"><div class="summary-item"><span>الحالة</span><strong>${r.status}</strong></div><div class="summary-item"><span>السيارة</span><strong>${vehicle(r.vehicleId)?.code}</strong></div><div class="summary-item"><span>السائق</span><strong>${r.driver}</strong></div><div class="summary-item"><span>المنطقة</span><strong>${r.area}</strong></div></div><div class="timeline"><div class="timeline-item"><div class="timeline-dot">1</div><div><strong>تحميل السيارة</strong><span>${r.loaded.map(x=>productName(x.productId)+' '+x.qty).join('، ')}</span></div></div>${r.sold.length?`<div class="timeline-item"><div class="timeline-dot">2</div><div><strong>مبيعات الجولة</strong><span>${r.sold.reduce((a,x)=>a+x.qty,0)} وحدة مرتبطة بفواتير</span></div></div>`:''}<div class="timeline-item"><div class="timeline-dot">✓</div><div><strong>${r.status==='مغلقة'?'إغلاق الجولة':'الجولة مفتوحة'}</strong><span>${r.status==='مغلقة'?'تمت المطابقة والتسوية':'ما زالت البضاعة مع السيارة'}</span></div></div></div>`,`<button class="btn btn-light" data-action="close-modal">إغلاق</button>`,true)}
function purchasePreview(p){openModal('تفاصيل فاتورة الشراء',`<div class="print-invoice"><div class="invoice-head"><div><h1>شركة السريحي</h1><p>سند استلام وفاتورة شراء</p></div><div style="text-align:left"><h1>${p.number}</h1><p>${fmtDate(p.date)}</p></div></div><div class="invoice-meta"><div><span>المورد</span><strong>${supplier(p.supplierId)?.name}</strong></div><div><span>المرجع</span><strong>${p.doc||'—'}</strong></div><div><span>حالة السداد</span><strong>${p.status}</strong></div></div><table style="min-width:0"><thead><tr><th>الصنف</th><th>الكمية</th><th>الوحدة</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${p.lines.map(l=>`<tr><td>${productName(l.productId)}</td><td>${l.qty}</td><td>${l.unit}</td><td>${money(l.price)}</td><td>${money(l.qty*l.price)}</td></tr>`).join('')}</tbody></table><div class="totals-box"><div class="total-row final"><span>الإجمالي</span><b>${money(p.total)}</b></div><div class="total-row"><span>المدفوع</span><b>${money(p.paid)}</b></div><div class="total-row"><span>المتبقي</span><b>${money(p.total-p.paid)}</b></div></div></div>`,`<button class="btn btn-light" data-action="close-modal">إغلاق</button><button class="btn btn-primary" data-action="print-modal">⎙ طباعة</button>${p.status==='ملغاة'?'':'<button class="btn btn-danger" data-action="cancel-purchase" data-id="'+p.id+'">إلغاء المستند</button>'}`,true)}
function paymentForm(p={}){const type=p.partyType||'customer';openModal(p.id?'تعديل دفعة':'تسجيل دفعة جديدة',`<form data-form="payment" data-id="${p.id||''}"><div class="form-grid"><div class="field"><label>نوع الدفعة</label><select class="select-control" name="partyType"><option value="customer" ${type==='customer'?'selected':''}>تحصيل من عميل</option><option value="supplier" ${type==='supplier'?'selected':''}>دفعة لمورد</option></select></div><div class="field"><label>الطرف</label><select class="select-control" name="partyId">${type==='customer'?customerOptions(p.partyId):supplierOptions(p.partyId)}</select></div><div class="field"><label>المبلغ <i class="required">*</i></label><input class="input-control" name="amount" type="number" min="0.01" step=".01" required value="${p.amount||''}" /></div><div class="field"><label>التاريخ</label><input class="input-control" name="date" type="date" value="${p.date||today()}" /></div><div class="field"><label>طريقة الدفع</label><select class="select-control" name="method"><option ${p.method==='نقد'?'selected':''}>نقد</option><option ${p.method==='تحويل'?'selected':''}>تحويل</option><option ${p.method==='شيك'?'selected':''}>شيك</option></select></div><div class="field"><label>البيان</label><input class="input-control" name="note" placeholder="دفعة على الحساب" value="${esc(p.note)}" /></div></div></form>`,formButtons('إلغاء',p.id?'حفظ التعديل':'حفظ الدفعة'))}
function expenseForm(e={}){openModal(e.id?'تعديل مصروف':'إضافة مصروف',`<form data-form="expense" data-id="${e.id||''}"><div class="form-grid"><div class="field"><label>نوع المصروف</label><select class="select-control" name="type">${['وقود','صيانة','نقل','رواتب','مصاريف تشغيل','مصروفات أخرى'].map(type=>`<option ${e.type===type?'selected':''}>${type}</option>`).join('')}</select></div><div class="field"><label>المبلغ <i class="required">*</i></label><input class="input-control" name="amount" type="number" min="0.01" step=".01" required value="${e.amount||''}" /></div><div class="field"><label>التاريخ</label><input class="input-control" name="date" type="date" value="${e.date||today()}" /></div><div class="field"><label>الشخص المسؤول</label><input class="input-control" name="person" value="${esc(e.person||'محمد السريحي')}" /></div><div class="field full"><label>الوصف</label><textarea class="textarea-control" name="note">${esc(e.note)}</textarea></div></div></form>`,formButtons('إلغاء',e.id?'حفظ التعديل':'حفظ المصروف'))}
function returnForm(){openModal('تسجيل مرتجع',`<form data-form="return"><div class="form-grid"><div class="field"><label>نوع المرتجع</label><select class="select-control" name="type"><option>مرتجع مبيعات</option><option>مرتجع مشتريات</option><option>بضاعة تالفة</option><option>منتهية الصلاحية</option></select></div><div class="field"><label>الطرف</label><select class="select-control" name="partyId">${customerOptions()}</select></div><div class="field"><label>الصنف</label><select class="select-control" name="productId">${productOptions()}</select></div><div class="field"><label>الكمية</label><input class="input-control" name="qty" type="number" min="1" value="1" /></div><div class="field"><label>القيمة</label><input class="input-control" name="amount" type="number" min="0" step=".01" /></div><div class="field"><label>حالة البضاعة</label><select class="select-control" name="condition"><option>سليمة وتعود للمخزون</option><option>تالف — لا يدخل المخزون</option></select></div></div></form>`,formButtons('إلغاء','حفظ المرتجع'))}
function assetForm(){openModal('حركة أصول قابلة للإرجاع',`<form data-form="asset"><div class="form-grid"><div class="field"><label>نوع الأصل</label><select class="select-control" name="type">${data.assets.map(a=>`<option>${a.type}</option>`).join('')}</select></div><div class="field"><label>نوع الحركة</label><select class="select-control" name="direction"><option>تسليم إلى عميل</option><option>استلام من عميل</option><option>تالف</option></select></div><div class="field"><label>العميل</label><select class="select-control" name="customerId">${customerOptions()}</select></div><div class="field"><label>الكمية</label><input class="input-control" name="qty" type="number" min="1" value="1" /></div><div class="field full"><label>ملاحظات</label><input class="input-control" name="note" /></div></div></form>`,formButtons('إلغاء','حفظ الحركة'))}
function userForm(u={}){openModal(u.id?'تعديل المستخدم':'إضافة مستخدم',`<form data-form="user" data-id="${u.id||''}"><div class="form-grid"><div class="field"><label>الاسم</label><input class="input-control" name="name" required value="${esc(u.name)}" /></div><div class="field"><label>رقم الهاتف</label><input class="input-control" name="phone" value="${esc(u.phone)}" /></div><div class="field"><label>الدور</label><select class="select-control" name="role">${['مدير','مسؤول مخزن','بائع','محاسب'].map(x=>`<option ${u.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>الحالة</label><select class="select-control" name="status"><option>نشط</option><option>موقوف</option></select></div></div></form>`,formButtons('إلغاء',u.id?'حفظ التعديل':'إضافة المستخدم'))}

function submitForm(form){
  if(form && !form.checkValidity()){form.reportValidity();return}
  const fd=new FormData(form), f=Object.fromEntries(fd.entries()), type=form.dataset.form, id=form.dataset.id;
  if(type==='product'){const obj={...f,pack:Number(f.pack),buy:Number(f.buy),sell:Number(f.sell),wholesale:Number(f.wholesale),min:Number(f.min),max:Number(f.max),stock:Number(f.stock||0),damaged:0,status:'نشط',createdAt:today()};if(!obj.sku||!obj.name||![obj.pack,obj.buy,obj.sell,obj.wholesale,obj.min,obj.max,obj.stock].every(Number.isFinite)||obj.pack<=0||obj.buy<0||obj.sell<0||obj.wholesale<0||obj.min<0||obj.max<obj.min||obj.stock<0){showToast('تحقق من بيانات الصنف والأسعار والحدود','error');return}if(id){const old=product(id);obj.id=id;obj.stock=old.stock;obj.damaged=old.damaged||0;obj.status=old.status||'نشط';Object.assign(old,obj);addActivity('تعديل صنف',obj.name,obj.sku)}else{obj.id=uid('P');data.products.push(obj);if(obj.stock)movement(obj.id,obj.stock,'رصيد افتتاحي','—','المستودع الرئيسي',obj.sku);addActivity('إضافة صنف',obj.name,obj.sku)}save();closeModal();render();showToast('تم حفظ الصنف');return}
  if(type==='customer'){const old=id?customer(id):null;const obj={...f,credit:Number(f.credit)||0,balance:old?.balance||0,sales:old?.sales||0,payments:old?.payments||0,returns:old?.returns||0,status:old?.status||'نشط'};if(id){Object.assign(old,obj);addActivity('تعديل عميل',obj.name,obj.code)}else{obj.id=uid('CUS');data.customers.push(obj);addActivity('إضافة عميل',obj.name,obj.code)}save();closeModal();render();showToast('تم حفظ العميل');return}
  if(type==='supplier'){const old=id?supplier(id):null;const obj={...f,balance:old?.balance||0,purchases:old?.purchases||0,payments:old?.payments||0,returns:old?.returns||0,status:old?.status||'نشط'};if(id){Object.assign(old,obj);addActivity('تعديل مورد',obj.name,obj.code)}else{obj.id=uid('SUP');data.suppliers.push(obj);addActivity('إضافة مورد',obj.name,obj.code)}save();closeModal();render();showToast('تم حفظ المورد');return}
  if(type==='zone'){const code=String(f.code||'').trim().toUpperCase();if(!code||data.warehouseZones.some(z=>z.code===code)){showToast('رمز المنطقة مطلوب ويجب ألا يكون مكررًا','error');return}const z={id:uid('ZONE'),warehouseId:'wh-main',code,name:f.name||`منطقة ${code}`,storageType:f.storageType||'عام',status:f.status||'نشط',description:f.description||''};data.warehouseZones.push(z);addActivity('إضافة منطقة تخزين',z.name,z.id);save();closeModal();render();showToast('تمت إضافة المنطقة');return}
  if(type==='catalog'){const catalogType=form.dataset.catalogType,collection=catalogType==='categories'?data.categories:catalogType==='units'?data.units:data.departments,name=String(f.name||'').trim();if(!name){showToast('الاسم مطلوب','error');return}if(collection.some(row=>row.name===name&&row.id!==id)){showToast('هذا الاسم موجود مسبقًا','error');return}const old=id?collection.find(row=>row.id===id):null,obj={id:id||uid(catalogType==='categories'?'CAT':catalogType==='units'?'UNIT':'DEPT'),name,status:f.status||'نشط'};if(old)Object.assign(old,obj);else collection.unshift(obj);if(catalogType==='categories'&&!categories.includes(name))categories.push(name);if(catalogType==='units'&&!units.includes(name))units.push(name);addActivity(old?'تعديل كتالوج':'إضافة كتالوج',name,obj.id);save();closeModal();render();showToast(old?'تم التعديل بنجاح':'تمت الإضافة بنجاح');return}
  if(type==='driver'||type==='representative'){const collection=type==='driver'?data.drivers:data.salesRepresentatives,old=id?collection.find(row=>row.id===id):null,obj={...f,id:id||uid(type==='driver'?'DRV':'REP'),code:f.code||`${type==='driver'?'DRV':'REP'}-${String(collection.length+1).padStart(3,'0')}`,status:f.status||'نشط'};if(old)Object.assign(old,obj);else collection.unshift(obj);addActivity(old?'تعديل سجل':'إضافة سجل',`${type==='driver'?'سائق':'مندوب'} · ${obj.name}`,obj.id);save();closeModal();render();showToast(old?'تم التعديل بنجاح':'تمت الإضافة بنجاح');return}
  if(type==='vehicle'){const obj={...f};if(id){Object.assign(vehicle(id),obj)}else{obj.id=uid('V');data.vehicles.push(obj);addActivity('إضافة سيارة',obj.code,obj.plate)}save();closeModal();render();showToast('تم حفظ السيارة');return}
  if(type==='route'){const v=vehicle(f.vehicleId);const r={id:uid('R'),code:f.code,date:f.date,vehicleId:f.vehicleId,driver:v?.driver||'—',seller:v?.seller||'—',area:f.area||'—',outTime:f.outTime||'—',status:'مفتوحة',notes:f.notes||'',loaded:[],sold:[],returned:[],losses:[]};data.routes.unshift(r);data.meta.nextRoute++;if(v)v.status='في جولة';addActivity('إنشاء جولة',`${r.code} · ${v?.code||''}`,r.code);save();closeModal();render();showToast('تم إنشاء الجولة. أضف التحميل الآن');return}
  if(type==='purchase'){const lines=syncLineItems(form);if(!lines.length||lines.some(l=>!Number.isFinite(l.qty)||l.qty<=0||!Number.isFinite(l.price)||l.price<0)){showToast('أدخل كميات موجبة وأسعارًا صحيحة','error');return}const total=lines.reduce((a,l)=>a+l.qty*l.price,0),paid=Number(f.paid||0);if(!Number.isFinite(paid)||paid<0||paid>total){showToast('المبلغ المدفوع غير صحيح','error');return}const p={id:uid('PUR'),number:`PUR-${String(data.meta.nextPurchase++).padStart(4,'0')}`,date:f.date,supplierId:f.partyId,lines:lines.map(l=>({...l,unit:product(l.productId)?.unit})),subtotal:total,total,paid,status:paid>=total?'مدفوعة':paid?'آجل جزئي':'آجل',doc:'—'};data.purchases.unshift(p);const s=supplier(f.partyId);updatePartyBalance(s,{purchase:total,payment:paid},'supplier');lines.forEach(l=>{const pr=product(l.productId);pr.stock+=l.qty;movement(l.productId,l.qty,'استلام بضاعة',s?.name||'المورد','المستودع الرئيسي',p.number)});addActivity('استلام بضاعة',`${s?.name||''} · ${money(total)}`,p.number);save();closeModal();activeSection='purchases';render();showToast('تم حفظ الشراء وزيادة المخزون');return}
  if(type==='sale'){const lines=syncLineItems(form);if(!lines.length||lines.some(l=>!Number.isFinite(l.qty)||l.qty<=0||!Number.isFinite(l.price)||l.price<0)){showToast('أدخل كميات موجبة وأسعارًا صحيحة','error');return}const subtotal=lines.reduce((a,l)=>a+l.qty*l.price,0),discount=Number(f.discount||0),total=subtotal-discount,paid=Number(f.paid||0);if(!Number.isFinite(discount)||discount<0||discount>subtotal||!Number.isFinite(paid)||paid<0||paid>total){showToast('تحقق من الخصم والمبلغ المدفوع','error');return}for(const l of lines){const pr=product(l.productId);if(!pr||l.qty>pr.stock){showToast(`الكمية غير متوفرة من ${pr?.name||'الصنف'}`,'error');return}}const s={id:uid('S'),number:`INV-${data.meta.nextInvoice++}`,date:f.date,customerId:f.partyId,routeId:null,lines:lines.map(l=>({...l,total:l.qty*l.price})),subtotal,discount,total,paid,method:f.method,status:paid>=total?'مدفوعة':paid?'جزئية':'آجل'};data.sales.unshift(s);const c=customer(f.partyId);updatePartyBalance(c,{sale:total,payment:paid},'customer');lines.forEach(l=>{product(l.productId).stock-=l.qty;movement(l.productId,-l.qty,'بيع','المستودع الرئيسي',c?.name||'العميل',s.number)});addActivity('تسجيل فاتورة بيع',`${c?.name||''} · ${money(total)}`,s.number);save();closeModal();activeSection='sales';render();showToast('تم تسجيل البيع وخصم الكمية');return}
  if(type==='route-load'){const r=route(id), rows=[...form.querySelectorAll('.line-item')].slice(1);const loads=[];for(const row of rows){const pid=row.querySelector('.load-product').value,qty=Number(row.querySelector('.load-qty').value);if(!qty||qty<0)continue;const pr=product(pid);if(qty>pr.stock){showToast(`الكمية غير متوفرة في المستودع: ${pr.name}`,'error');return}loads.push({pid,qty})}if(!loads.length){showToast('أدخل صنفًا واحدًا على الأقل','error');return}for(const x of loads){const pr=product(x.pid),existing=r.loaded.find(l=>l.productId===x.pid);pr.stock-=x.qty;if(existing)existing.qty+=x.qty;else r.loaded.push({productId:x.pid,qty:x.qty});movement(x.pid,-x.qty,'تحميل سيارة','المستودع الرئيسي',vehicle(r.vehicleId)?.code||'السيارة',r.code)}addActivity('تحميل سيارة',`${r.code} · ${loads.reduce((a,x)=>a+x.qty,0)} وحدة`,r.code);save();closeModal();render();showToast('تم تحميل السيارة ونقل المخزون');return}
  if(type==='route-sale'){const r=route(id), rows=[...form.querySelectorAll('.route-sale-line')], lines=[];for(const row of rows){const qty=Number(row.querySelector('.route-qty').value),price=Number(row.querySelector('.route-price').value);if(!Number.isFinite(qty)||!Number.isFinite(price)||qty<0||price<0){showToast('الكمية والسعر يجب أن يكونا صحيحين','error');return}if(qty>0){const pid=row.dataset.product,available=routeAvailable(r,pid);if(qty>available){showToast(`الكمية المتوفرة مع السيارة: ${available}`,'error');return}lines.push({productId:pid,qty,price,total:qty*price})}}if(!lines.length){showToast('أدخل كمية مباعة واحدة على الأقل','error');return}const total=lines.reduce((a,l)=>a+l.total,0),paid=Number(f.paid||0);if(!Number.isFinite(paid)||paid<0||paid>total){showToast('المبلغ المدفوع غير صحيح','error');return}const s={id:uid('S'),number:`INV-${data.meta.nextInvoice++}`,date:f.date,customerId:f.customerId,routeId:r.id,lines,subtotal:total,discount:0,total,paid,method:f.method,status:paid>=total?'مدفوعة':paid?'جزئية':'آجل'};data.sales.unshift(s);const c=customer(f.customerId);updatePartyBalance(c,{sale:total,payment:paid},'customer');lines.forEach(l=>{r.sold.push({productId:l.productId,qty:l.qty,saleId:s.id});movement(l.productId,-l.qty,'بيع من سيارة',vehicle(r.vehicleId)?.code||'السيارة',c?.name||'العميل',s.number)});addActivity('بيع من جولة',`${r.code} · ${c?.name||''} · ${money(total)}`,s.number);save();closeModal();render();showToast('تم تسجيل البيع. تم تحديث رصيد السيارة');return}
  if(type==='close-route'){const r=route(id),rows=[...form.querySelectorAll('.close-line')], returns=[],losses=[];for(const row of rows){const pid=row.dataset.product,available=routeAvailable(r,pid),ret=Number(row.querySelector('.return-qty').value||0),loss=Number(row.querySelector('.loss-qty').value||0),lossType=row.querySelector('.loss-type').value;if(!Number.isFinite(ret)||!Number.isFinite(loss)||ret<0||loss<0||ret+loss!==available){showToast(`الفرق غير مبرر في ${productName(pid)}. يجب أن يساوي المرتجع + الفرق = ${available}.`,'error');return}if(loss>0&&!lossType){showToast(`حدد نوع الفرق في ${productName(pid)}`,'error');return}if(ret)returns.push({productId:pid,qty:ret});if(loss)losses.push({productId:pid,qty:loss,type:lossType})}for(const x of returns){product(x.productId).stock+=x.qty;movement(x.productId,x.qty,'مرتجع من السيارة',vehicle(r.vehicleId)?.code||'السيارة','المستودع الرئيسي',r.code)}for(const x of losses){product(x.productId).damaged+=x.qty;movement(x.productId,-x.qty,'تالف/فاقد',vehicle(r.vehicleId)?.code||'السيارة',x.type,r.code)}r.returned=returns;r.losses=losses;r.closeNotes=f.notes||'';r.status='مغلقة';const v=vehicle(r.vehicleId);if(v)v.status='متاحة';addActivity('إغلاق جولة',`${r.code} · مرتجع ${returns.reduce((a,x)=>a+x.qty,0)} وحدة`,r.code);save();closeModal();render();showToast('تم إغلاق الجولة وتسوية مخزون السيارة');return}
  if(type==='payment'){const amount=Number(f.amount),party=f.partyType==='customer'?customer(f.partyId):supplier(f.partyId),old=id?data.payments.find(row=>row.id===id):null;if(!Number.isFinite(amount)||amount<=0||!party){showToast('أدخل مبلغًا صحيحًا وحدد الطرف','error');return}if(old){const oldParty=old.partyType==='customer'?customer(old.partyId):supplier(old.partyId);if(oldParty)updatePartyBalance(oldParty,{payment:-Number(old.amount||0)},old.partyType);Object.assign(old,{date:f.date,partyType:f.partyType,partyId:f.partyId,amount,method:f.method,note:f.note})}else{const p={id:uid('PAY'),date:f.date,partyType:f.partyType,partyId:f.partyId,amount,method:f.method,note:f.note};data.payments.unshift(p)}updatePartyBalance(party,{payment:amount},f.partyType);addActivity(old?'تعديل دفعة':'تسجيل دفعة',`${f.partyType==='customer'?'تحصيل من عميل':'دفعة مورد'} · ${money(amount)}`,old?.id||'PAY');save();closeModal();render();showToast(old?'تم تعديل الدفعة وتحديث الرصيد':'تم تسجيل الدفعة وتحديث الرصيد');return}
  if(type==='expense'){const amount=Number(f.amount);if(!Number.isFinite(amount)||amount<=0){showToast('المبلغ يجب أن يكون موجبًا','error');return}const old=id?data.expenses.find(row=>row.id===id):null,e={id:id||uid('EXP'),date:f.date,type:f.type,amount,person:f.person,note:f.note};if(old)Object.assign(old,e);else data.expenses.unshift(e);addActivity(old?'تعديل مصروف':'إضافة مصروف',`${e.type} · ${money(e.amount)}`,e.id);save();closeModal();render();showToast(old?'تم تعديل المصروف':'تم حفظ المصروف');return}
  if(type==='return'){
    const qty=Number(f.qty),pr=product(f.productId),isCustomer=(f.partyType||'customer')==='customer',party=isCustomer?customer(f.partyId):supplier(f.partyId);
    if(!Number.isFinite(qty)||qty<=0||!pr||!party){showToast('بيانات المرتجع غير صحيحة','error');return}
    const sourceDocs=isCustomer?data.sales.filter(s=>s.customerId===party.id&&s.status!=='ملغاة'):data.purchases.filter(p=>p.supplierId===party.id&&p.status!=='ملغاة');
    const originalQty=sourceDocs.reduce((total,doc)=>(doc.lines||[]).reduce((sum,line)=>sum+(line.productId===pr.id?Number(line.qty)||0:0),total),0);
    const priorQty=data.returns.filter(r=>(r.partyType||'customer')===(isCustomer?'customer':'supplier')&&(r.partyId===party.id||r[isCustomer?'customerId':'supplierId']===party.id)&&r.productId===pr.id).reduce((total,r)=>total+(Number(r.qty)||0),0);
    if(qty>Math.max(0,originalQty-priorQty)){showToast(`لا يمكن إرجاع أكثر من الكمية الأصلية. المتاح للمرتجع: ${Math.max(0,originalQty-priorQty)}`,'error');return}
    const amount=Number(f.amount||qty*(isCustomer?pr.sell:pr.buy));if(!Number.isFinite(amount)||amount<0){showToast('قيمة المرتجع غير صحيحة','error');return}
    const good=f.condition==='سليمة وتعود للمخزون';
    if(isCustomer&&good){pr.stock+=qty;movement(f.productId,qty,'مرتجع بيع',party.name,'المستودع الرئيسي',`RET-${Date.now().toString().slice(-4)}`)}
    else if(!isCustomer){if(Number(pr.stock||0)<qty){showToast('المخزون الحالي لا يكفي لإرجاع الكمية إلى المورد','error');return}pr.stock-=qty;movement(f.productId,-qty,'مرتجع شراء','المستودع الرئيسي',party.name,`RET-${Date.now().toString().slice(-4)}`)}
    else{pr.damaged+=qty;movement(f.productId,0,'مرتجع بيع تالف',party.name,'مخزون تالف',`DMG-${Date.now().toString().slice(-4)}`)}
    const ref=(good?'RET-':'DMG-')+Date.now().toString().slice(-4);
    updatePartyBalance(party,{return:amount},isCustomer?'customer':'supplier');
    data.returns.unshift({id:uid('RET'),ref,date:today(),type:f.type,party:party.name,partyId:party.id,customerId:isCustomer?party.id:undefined,supplierId:isCustomer?undefined:party.id,productId:pr.id,product:pr.name,qty,unit:pr.unit,amount,condition:f.condition,partyType:f.partyType||'customer',note:f.note||''});
    addActivity('تسجيل مرتجع',`${pr.name} · ${qty} ${pr.unit}`,ref);save();closeModal();render();showToast('تم تسجيل المرتجع وتحديث المخزون');return
  }
  if(type==='asset'){const a=data.assets.find(x=>x.type===f.type),qty=Number(f.qty);if(!a||!Number.isFinite(qty)||qty<=0){showToast('بيانات الحركة غير صحيحة','error');return}a.available=Number(a.available)||0;a.withCustomers=Number(a.withCustomers)||0;a.withVehicles=Number(a.withVehicles)||0;a.damaged=Number(a.damaged)||0;a.lost=Number(a.lost)||0;if(f.direction==='تسليم إلى عميل'){if(qty>a.available){showToast('الكمية المتاحة من الأصل غير كافية','error');return}a.available-=qty;a.withCustomers+=qty}else if(f.direction==='استلام من عميل'){if(qty>a.withCustomers){showToast('الكمية مع العملاء غير كافية','error');return}a.available+=qty;a.withCustomers-=qty}else if(f.direction==='تالف'||f.direction==='مفقود'){if(qty>a.available){showToast('الكمية المتاحة من الأصل غير كافية','error');return}a.available-=qty;a[f.direction==='تالف'?'damaged':'lost']+=qty}else{showToast('نوع حركة الأصول غير مدعوم','error');return}a.total=Math.max(0,a.available+a.withCustomers+a.withVehicles+a.damaged+a.lost);a.movements.unshift({id:uid('AM'),date:today(),direction:f.direction,qty,note:f.note||''});addActivity('حركة أصول',`${f.direction} · ${f.type} · ${qty}`,'ASSET');save();closeModal();render();showToast('تم تحديث رصيد الأصول');return}
  if(type==='user'){const obj={...f};if(id)Object.assign(data.users.find(x=>x.id===id),obj);else{obj.id=uid('USR');data.users.push(obj)}save();closeModal();render();showToast('تم حفظ المستخدم');return}
}

document.addEventListener('click',e=>{
  const pager=e.target.closest('[data-page]');
  if(pager){pageState[pager.dataset.page]=Number(pager.dataset.pageNumber)||1;render();return}
  const nav=e.target.closest('[data-section]');
  if(nav){navigateToSection(nav.dataset.section);return}
  const report=e.target.closest('[data-report]');
  if(report){activeReport=report.dataset.report;render();return}
  const action=e.target.closest('[data-action]');
  if(action){handleAction(action.dataset.action,action)}
});
document.addEventListener('submit',e=>{e.preventDefault();submitForm(e.target)});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape')closeModal();
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch').focus()}
  if(e.key==='Enter'&&e.target.classList.contains('local-search')){searchTerm=e.target.value.trim();render()}
});
document.addEventListener('input',e=>{
  if(e.target.classList.contains('local-search')){searchTerm=e.target.value.trim();render();const next=document.querySelector('.local-search');if(next){next.focus();next.setSelectionRange(next.value.length,next.value.length)}return}
  if(e.target.classList.contains('stock-count')){const p=product(e.target.dataset.id),diff=Number(e.target.value)-p.stock,tag=document.querySelector(`[data-diff="${e.target.dataset.id}"]`);if(tag){tag.textContent=diff>0?`+${diff}`:diff;tag.className=`badge ${diff===0?'badge-neutral':diff>0?'badge-success':'badge-danger'}`}}
  if(e.target.classList.contains('line-qty')||e.target.classList.contains('line-price')){const row=e.target.closest('.line-item[data-line]'),i=Number(row?.dataset.line);if(row&&currentLineItems[i]){currentLineItems[i].qty=Number(row.querySelector('.line-qty').value)||0;currentLineItems[i].price=Number(row.querySelector('.line-price').value)||0;const total=row.querySelector('.line-total');if(total)total.innerHTML=money(currentLineItems[i].qty*currentLineItems[i].price);const totals=document.getElementById('lineTotals');if(totals)totals.innerHTML=lineTotals();decorateNumericContent(document.getElementById('modal'))}}
  if(e.target.name==='discount'){const subtotal=currentLineItems.reduce((a,l)=>a+(Number(l.qty)||0)*(Number(l.price)||0),0),discount=Math.max(0,Number(e.target.value)||0),total=Math.max(0,subtotal-discount),final=document.querySelector('#lineTotals .total-row.final b');if(final)final.innerHTML=money(total)}
  if(e.target.classList.contains('route-qty')||e.target.classList.contains('route-price')){const form=e.target.closest('form'),total=[...form.querySelectorAll('.route-sale-line')].reduce((a,row)=>a+(Number(row.querySelector('.route-qty').value)||0)*(Number(row.querySelector('.route-price').value)||0),0),out=form.querySelector('#routeSaleTotal');if(out)out.innerHTML=money(total);decorateNumericContent(document.getElementById('modal'))}
});
document.getElementById('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('dark');data.meta.theme=document.body.classList.contains('dark')?'dark':'light';save()});
function closeMobileSidebar(){
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('sidebarOverlay').classList.remove('open');
  document.getElementById('mobileMenu').setAttribute('aria-expanded','false');
}
function toggleMobileSidebar(){
  const isOpen=document.getElementById('sidebar').classList.toggle('open');
  document.getElementById('sidebarOverlay').classList.toggle('open',isOpen);
  document.getElementById('mobileMenu').setAttribute('aria-expanded',String(isOpen));
}
document.getElementById('mobileMenu').addEventListener('click',toggleMobileSidebar);
document.getElementById('sidebarOverlay').addEventListener('click',closeMobileSidebar);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileSidebar()});
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){searchTerm=e.target.value.trim();navigateToSection('products')}});
