// Keep party selector useful in payment form when switching between customer and supplier.
document.addEventListener('change',e=>{
  if(e.target.dataset.filter||e.target.classList.contains('product-category-filter')){filters[e.target.dataset.filter||'productsCategory']=e.target.value;render();return}
  if(e.target.dataset.setting==='currency'){data.meta.currency=e.target.value;save();render();return}
  if(e.target.dataset.setting==='tax'){data.meta.taxEnabled=e.target.value==='true';save();return}
  if(e.target.name==='partyType'){
    const select=e.target.closest('form')?.querySelector('[name="partyId"]');
    if(select)select.innerHTML=e.target.value==='customer'?customerOptions():supplierOptions();
  }
  if(e.target.classList.contains('load-product')){const p=product(e.target.value),available=e.target.closest('.line-item')?.querySelector('.load-available');if(available)available.textContent=p?.stock||0}
});

function saveStocktakeDraft(){const rows=[...document.querySelectorAll('.stock-count')],lines=rows.map(input=>{const p=product(input.dataset.id),actual=Number(input.value);return {productId:p.id,system:p.stock,actual:Number.isFinite(actual)&&actual>=0?actual:p.stock,diff:(Number.isFinite(actual)&&actual>=0?actual:p.stock)-p.stock,reason:input.closest('tr')?.querySelector('input:not(.stock-count)')?.value?.trim()||''}});const draft={id:uid('STK'),date:today(),lines,status:'مسودة'};data.stocktakes.unshift(draft);data.inventoryCounts.unshift(draft);addActivity('حفظ جرد كمسودة',`${lines.length} صنف`,draft.id);save();render();showToast('تم حفظ ورقة الجرد كمسودة')}
function confirmStocktake(){const rows=[...document.querySelectorAll('.stock-count')],lines=[];rows.forEach(input=>{const p=product(input.dataset.id),actual=Number(input.value),reason=input.closest('tr')?.querySelector('input:not(.stock-count)')?.value?.trim()||'';if(!Number.isFinite(actual)||actual<0)return;const diff=actual-p.stock;lines.push({productId:p.id,system:p.stock,actual,diff,reason});if(diff){p.stock=actual;movement(p.id,diff,'تسوية جرد','الجرد','المستودع الرئيسي','STK-'+Date.now().toString().slice(-4),reason);data.inventoryAdjustments.unshift({id:uid('ADJ'),date:today(),productId:p.id,quantity:diff,reason,type:'تسوية جرد'})}});const count={id:uid('STK'),date:today(),lines,status:'مؤكد'};data.stocktakes.unshift(count);data.inventoryCounts.unshift(count);addActivity('تأكيد جرد',`${lines.filter(x=>x.diff).length} فروقات تمت تسويتها`,count.id);save();render();showToast('تم تأكيد الجرد وتسجيل التسويات')}

