  return pageTitle('المدفوعات','تحصيلات العملاء ودفعات الموردين والحركة النقدية','<button class="btn btn-primary" data-action="add-payment">＋ تسجيل دفعة</button>')+'<div class="summary-strip"><div class="summary-item"><span>تحصيلات العملاء</span><strong>'+money(sum(data.payments.filter(p=>p.partyType==='customer')))+'</strong></div><div class="summary-item"><span>دفعات الموردين</span><strong>'+money(sum(data.payments.filter(p=>p.partyType==='supplier')))+'</strong></div><div class="summary-item"><span>دفعات اليوم</span><strong>'+money(sum(data.payments.filter(p=>p.date===today())))+'</strong></div><div class="summary-item"><span>الرصيد النقدي</span><strong>'+money(sum(data.payments.filter(p=>p.partyType==='customer'))-sum(data.payments.filter(p=>p.partyType==='supplier')))+'</strong></div></div><div class="card table-card"><div class="card-header"><h3>سجل المدفوعات</h3><div class="table-tools">'+tableSearch('رقم السند أو الطرف')+'</div></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>نوع الحركة</th><th>الطرف</th><th>طريقة الدفع</th><th>المبلغ</th><th>البيان</th><th>إجراء</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';
