  const cards=data.assets.map(a=>'<div class="summary-item"><span>'+esc(a.type)+'</span><strong>'+num(a.total)+' <span class="muted small">إجمالي</span></strong><small class="muted">'+num(a.available)+' بالمستودع · '+num(a.withVehicles)+' مع السيارات · '+num(a.withCustomers)+' مع العملاء</small></div>').join('');
